    this.fd = d.fd || null;
    this.items = this.fd ? this.fd.items : [];
    this.itemById = new Map(this.items.map(f => [f.id, f]));
    this.itemByRef = new Map(this.items.filter(f => f.ref !== undefined).map(f => [f.ref, f]));
