  inkPage(v) {
    const b = this.block(v);
    if (!v.ix || !b || !b.bi || !b.x) return null;
    const mx = b.bi.w / (b.x[2] - b.x[0]), my = b.bi.h / (b.x[3] - b.x[1]);
    return [b.x[0] + v.ix[0] / mx, b.x[1] + v.ix[1] / my, b.x[0] + v.ix[2] / mx, b.x[1] + v.ix[3] / my];
