    this.sw = A.r - A.l; this.sh = this.sw * pg.h / pg.w; this.k = this.sw / pg.w;
    const st = this.pose.style;
    st.setProperty('--w', `${this.sw}px`); st.setProperty('--h', `${this.sh}px`);
    st.setProperty('--depth', `${this.stackCount() * 2}px`);
    this.viewport.style.perspectiveOrigin = `${this.viewport.clientWidth / 2}px ${(A.t + A.b) / 2}px`;
    this.base = this.fit();
    this.setP(this.target());
    if (this.loupe) this.loupe.relayout();
    if (this.partial) this.updateFlat();
    this.updateLeader();
  }
  stackCount() { return Math.min(5, this.store.pages.length - 1); }

  // the sheet's projected box, relative to the stage, with the pointer lean taken out
  measure(P) {
    this.setP(P);
    const lean = this.leanEl.style.transform;
    this.leanEl.style.transform = 'none';
    const r = this.sheet.getBoundingClientRect(), v = this.viewport.getBoundingClientRect();
    this.leanEl.style.transform = lean;
    return { l: r.left - v.left, t: r.top - v.top, w: r.width, h: r.height, r: r.right - v.left, b: r.bottom - v.top };
  }
  fit() {
    const A = this.area(), sa = this.stackPx();
    const sx = this.flat ? 0 : SLACK_X, sy = this.flat ? 0 : SLACK_Y;   // room for the turn toward a value, tilted only
    const box = { l: A.l + sx, r: A.r - sx - sa, t: A.t + sy, b: A.b - sy - sa };
    const P = { f: 0.5, tx: (box.l + box.r) / 2, ty: (box.t + box.b) / 2, rx: this.flat ? 0 : TILT_X, rz: this.flat ? 0 : TILT_Z };
    for (let n = 0; n < 5; n++) {
      let m = this.measure(P);
      P.f *= Math.min((box.r - box.l) / m.w, (box.b - box.t) / m.h);
      m = this.measure(P);
      P.tx += (box.l + box.r) / 2 - (m.l + m.r) / 2;
      P.ty += (box.t + box.b) / 2 - (m.t + m.b) / 2;
    }
    return P;
  }
  // the pose for the current selection: a small turn toward the value, never out of the sheet zone
  target() {
    const keep = { ...this.P };
    const v = this.store && this.sel !== null ? this.store.values[this.sel] : null;
    if (!v || !v.x || v.p !== this.page || this.flat) return { ...this.base };
    const pg = this.pg;
    const nx = ((v.x[0] + v.x[2]) / 2 / pg.w - 0.5) * 2, ny = ((v.x[1] + v.x[3]) / 2 / pg.h - 0.5) * 2;
    const P = { ...this.base, rz: this.base.rz - TURN_Z * nx, tx: this.base.tx - nx * SLACK_X, ty: this.base.ty - ny * SLACK_Y };
    const A = this.area(), sa = this.stackPx();
    for (let n = 0; n < 2; n++) {
      const m = this.measure(P);
      P.tx += Math.max(0, A.l - m.l) - Math.max(0, m.r + sa - A.r);
      P.ty += Math.max(0, A.t - m.t) - Math.max(0, m.b + sa - A.b);
    }
    this.setP(keep);
    return P;
  }
  setP(P) {
    this.P = P;
    this.pose.style.transform = `translate(${P.tx}px, ${P.ty}px) rotateX(${P.rx}deg) rotateZ(${P.rz}deg) scale(${P.f})`;
    const st = this.pose.style;
    st.setProperty('--u', 1 / (this.k * P.f)); st.setProperty('--inv', 1 / P.f);
    const u = 1 / (this.k * P.f);
    for (const p of this.tickPaths || []) p.setAttribute('transform', `scale(${u.toFixed(4)})`);
  }
  go(P, ms) {
    cancelAnimationFrame(this.tw);
    const A = { ...this.P };
    if (!ms || this.reduced) { this.setP(P); this.updateLeader(); return; }
    const t0 = performance.now();
    const step = now => {
      const t = Math.min(1, (now - t0) / ms), e = ease(t);
      this.setP({ f: mix(A.f, P.f, e), tx: mix(A.tx, P.tx, e), ty: mix(A.ty, P.ty, e), rx: mix(A.rx, P.rx, e), rz: mix(A.rz, P.rz, e) });
      this.updateLeader();
      if (t < 1) this.tw = requestAnimationFrame(step);
    };
    this.tw = requestAnimationFrame(step);
  }

  // ---- the leader: loupe's bottom edge to the ring on the sheet, followed on every frame while anything moves
  pump(ms) {
    this.until = Math.max(this.until, performance.now() + ms);
    if (this.pumping) return;
    this.pumping = true;
    const step = () => {
      this.updateLeader();
      if (performance.now() < this.until) requestAnimationFrame(step); else this.pumping = false;
    };
    requestAnimationFrame(step);
  }
  updateLeader() {
    const line = this.leaderLine, ringEl = this.loupe && this.loupe.ringEl, a = this.anchor;
    if (this.partial || !ringEl || !ringEl.isConnected || !a || !a.isConnected) { line.setAttribute('hidden', ''); return; }
    const o = this.leader.getBoundingClientRect(), lb = this.loupeEl.getBoundingClientRect();
    const rb = ringEl.getBoundingClientRect(), ab = a.getBoundingClientRect();
    if (!ab.width || !rb.width) { line.setAttribute('hidden', ''); return; }
    const sx = Math.min(Math.max(rb.left + rb.width / 2, lb.left + 12), lb.right - 12), sy = lb.bottom;
    const cx = ab.left + ab.width / 2, cy = ab.top + ab.height / 2, rx = ab.width / 2, ry = ab.height / 2;
    const dx = sx - cx, dy = sy - cy, t = 1 / Math.hypot(dx / rx, dy / ry);
    line.setAttribute('x1', sx - o.left); line.setAttribute('y1', sy - o.top);
    line.setAttribute('x2', cx + dx * t - o.left); line.setAttribute('y2', cy + dy * t - o.top);
    line.removeAttribute('hidden');
  }

  // ---- pages
  async setPage(n, animate = true, dir = 1) {
    if (n === this.page) return;
    const first = this.page === null;
    const leaving = !first && animate && !this.reduced ? this.paper.cloneNode(true) : null;
    this.page = n;
    const pg = this.pg;
    this.stack.replaceChildren(...Array.from({ length: this.stackCount() }, (_, i) => {
      const e = document.createElement('i');
      const d = `calc(var(--inv, 1) * ${(i + 1) * STACK_PX}px)`;
      e.style.transform = `translate3d(${d}, ${d}, calc(var(--inv, 1) * ${-(i + 1) * 2}px))`;
      e.style.background = ['#c9c6b8', '#bfbcae', '#b5b2a4', '#abaa9b', '#a1a092'][i];
      return e;
    }));
    const depth = this.stackCount(), d = `calc(var(--inv, 1) * ${(depth + 1) * STACK_PX}px)`;
    const under = document.createElement('i');   // the contact shadow, lowest in the pile
    under.className = 'under';
    under.style.transform = `translate3d(${d}, ${d}, calc(var(--inv, 1) * ${-(depth + 1) * 2}px))`;
    this.stack.prepend(under);
    this.clearBands();
    this.anchor = null;
    this.layout(true);
    this.buildMarks();
    this.notice.hidden = true;
    this.setPartial(this.forcePartial);
    if (!this.forcePartial) await new Promise(res => {
      this.scan.onload = () => { loaded(); res(); };
      this.scan.onerror = () => {
        // no page image: the block's own image is shown flat instead, and only when there is none is it an error
        if (this.hasBlockImage()) this.setPartial(true);
        else { this.notice.textContent = this.onError(pg.img); this.notice.hidden = false; }
        res();
      };
      this.scan.src = pg.img;
    });
    if (leaving) {
      this.pump(PAGE_MS + 100);
      leaving.removeAttribute('id'); leaving.removeAttribute('role');
      leaving.querySelectorAll('[id]').forEach(e => e.removeAttribute('id'));
      leaving.style.pointerEvents = 'none';
      this.paper.before(leaving);
      leaving.animate([{ transform: 'translate3d(0,0,0)', opacity: 1 },
                       { transform: `translate3d(${-dir * this.sw * 0.7}px, ${this.sh * 0.08}px, 30px) rotateZ(${-dir * 5}deg)`, opacity: 0 }],
                      { duration: PAGE_MS, easing: 'cubic-bezier(.77,0,.175,1)' }).finished.then(() => leaving.remove(), () => leaving.remove());
      for (const e of [this.paper, this.marks])
        e.animate([{ transform: `translate3d(${dir * 6}px, 6px, -6px)` }, { transform: e === this.marks ? 'translateZ(.5px)' : 'none' }],
                  { duration: PAGE_MS, easing: 'cubic-bezier(.23,1,.32,1)' });
    }
  }

  // ---- marks: one focusable rectangle per value that has a box
  buildMarks() {
    const pg = this.pg, m = this.marks;
    m.replaceChildren();
    m.setAttribute('viewBox', `0 0 ${pg.w} ${pg.h}`);
    this.bands.setAttribute('viewBox', `0 0 ${pg.w} ${pg.h}`);
    this.rects = [];
    for (const i of this.store.byPage.get(this.page) || []) {
      const v = this.store.values[i];
      if (!v.x) continue;
      const r = svg('rect', { x: v.x[0], y: v.x[1], width: v.x[2] - v.x[0], height: v.x[3] - v.x[1], tabindex: -1, role: 'button' });
      r.dataset.i = i; r.dataset.b = v.b;
      r.addEventListener('focus', () => { this.showFocus(v.x); this.onFocusValue(i); });
      r.addEventListener('blur', () => { this.showFocus(null); setTimeout(() => { if (!this.marks.contains(document.activeElement)) this.onFocusValue(null); }); });
      if (this.store.isTotal(v)) r.classList.add('total');
      r.setAttribute('aria-label', `${v.v}, ${this.store.rowLabel(v)} ${this.store.colLabel(v)}`.trim());
      r.addEventListener('click', () => this.onPick(i));
      r.addEventListener('keydown', e => this.keys(e, r));
      m.append(r);
      this.rects.push({ r, i, cx: (v.x[0] + v.x[2]) / 2, cy: (v.x[1] + v.x[3]) / 2 });
    }
    this.ticks = new Map(); this.tickPaths = [];   // a pencil tick at every finding's value on this page (the selected one has its ring instead)
    const tg = svg('g', { class: 'ticks', 'aria-hidden': 'true' });
    for (const f of this.store.items) {
      const v = f.ref === undefined ? null : this.store.values[f.ref];
      if (!v || !v.x || v.p !== this.page) continue;
      const g = svg('g', { transform: `translate(${v.x[0]} ${(v.x[1] + v.x[3]) / 2})`, class: 'tick ' + (f.status === 'settled_against_file' ? 'settled' : 'open') });
      const path = svg('path', { d: 'M3 0L7 5L15 -7' });
      g.append(path);
      this.tickPaths.push(path);
      tg.append(g);
      this.ticks.set(f.ref, g);
    }
    m.prepend(tg);
    this.focusRing = svg('g', { class: 'focus-ring', 'aria-hidden': 'true' });
    for (const cls of ['dark', 'light']) this.focusRing.append(svg('rect', { class: cls }));
    this.focusRing.setAttribute('display', 'none');
    m.append(this.focusRing);
    this.markSelected();
  }
  // two strokes round the focused value, so it shows on white paper: ink outside, --focus inside, 2 px
  showFocus(b) {
    const g = this.focusRing;
    if (!g) return;
    if (!b) { g.setAttribute('display', 'none'); return; }
    for (const r of g.children) {
      r.setAttribute('x', b[0] - 1); r.setAttribute('y', b[1] - 1);
      r.setAttribute('width', b[2] - b[0] + 2); r.setAttribute('height', b[3] - b[1] + 2);
    }
    g.removeAttribute('display');
  }
  markSelected() {
    for (const [r, g] of this.ticks || []) { if (r === this.sel) g.setAttribute('display', 'none'); else g.removeAttribute('display'); }
    for (const o of this.rects || []) o.r.setAttribute('tabindex', o.i === this.sel ? 0 : -1);
    if (!this.rects.some(o => o.i === this.sel) && this.rects[0]) this.rects[0].r.setAttribute('tabindex', 0);
  }
  keys(e, r) {
    const i = +r.dataset.i;
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.onPick(i); return; }
    const dirs = { ArrowRight: [1, 0], ArrowLeft: [-1, 0], ArrowDown: [0, 1], ArrowUp: [0, -1] };
    const d = dirs[e.key];
    if (!d) return;
    e.preventDefault();
    const cur = this.rects.find(o => o.i === i);
    let best = null, bs = Infinity;
    const inBlock = this.rects.filter(o => o.r.dataset.b === r.dataset.b);
    for (const o of this.rects.length && inBlock.some(o => o !== cur && (o.cx - cur.cx) * d[0] + (o.cy - cur.cy) * d[1] >= 4) ? inBlock : this.rects) {
      const dx = o.cx - cur.cx, dy = o.cy - cur.cy;
      const along = dx * d[0] + dy * d[1], across = Math.abs(dx * d[1] - dy * d[0]);
      if (along < 4) continue;
      const score = along + across * 4;
      if (score < bs) { bs = score; best = o; }
    }
    if (best) { r.setAttribute('tabindex', -1); best.r.setAttribute('tabindex', 0); best.r.focus(); }
  }

  // ---- the bands
  clearBands() { this.bands.replaceChildren(); }
  async select(i, sums, animate = true, opts = {}) {
    const tk = ++this.token;
    this.sel = i;
    this.clearBands();
    this.markSelected();
    const instant = !animate || this.reduced;
    const first = sums.slice().sort((a, b) => (a.axis === 'row' ? -1 : 1) - (b.axis === 'row' ? -1 : 1));
    const draws = first.map(s => ({ ...s, line: this.store.band(s.check) })).filter(s => s.line);
    const v = this.store.values[i];
    const ring = v.x ? this.ringFor(v, draws) : null;
    this.anchor = null;
    if (ring) {
      this.anchor = svg('circle', { cx: ring.x, cy: ring.y, r: ring.r, fill: 'none', stroke: 'none' });
      this.bands.append(this.anchor);
    }
    const loupeDraws = draws.map(d => ({ line: d.line, ok: d.check.ok, axis: d.axis }));
    if (this.loupe) this.loupe.show(this.store, i, loupeDraws, !instant, opts.extra || {});
    this.flatArgs = { v, draws: loupeDraws };
    if (this.partial) this.updateFlat();
    if (opts.settle) {   // the first load: the sheet settles from flat into its tilt
      const keep = { ...this.P };
      this.flat = false; this.base = this.fit();
      this.setP(keep);
    }
    if (v.x) this.go(this.target(), instant ? 0 : opts.settle ? ENTER_MS : TURN_MS);
    this.updateLeader();
    if (instant) {
      draws.forEach(s => this.band(s, true));
      if (ring) this.svgRing(ring, true);
      if (this.loupe) this.loupe.reveal(false);
      return true;
    }
    if (opts.settle) {   // the entrance: the sheet settles while the bands draw together, then the ring closes
      this.pump(ENTER_MS + 150);
      await wait(60);
      await Promise.all(draws.map(s => this.band(s, false, 260)));
      if (tk !== this.token) return false;
      await Promise.all([ring ? this.svgRing(ring, false, 120) : null, this.loupe ? this.loupe.reveal(true, 120) : null]);
      return tk === this.token;
    }
    this.pump(TURN_MS + 150);
    if (v.x) await wait(TURN_MS);
    for (const s of draws) {
      if (tk !== this.token) return false;
      await this.band(s, false);
    }
    if (tk !== this.token) return false;
    await Promise.all([ring ? this.svgRing(ring, false) : null, this.loupe ? this.loupe.reveal(true) : null]);
    return tk === this.token;
  }
  // a finding with no place on the sheet: nothing is ringed, no sum is drawn; the sheet stays where it is
  deselect() {
    this.token++;
    this.sel = null;
    this.clearBands();
    this.anchor = null;
    this.flatArgs = null;
    this.markSelected();
    this.go(this.target(), 0);
    this.updateLeader();
  }
  ringFor(v, draws) {
    const h = v.x[3] - v.x[1], ink = this.store.inkPage(v) || v.x;
    return { x: (ink[0] + ink[2]) / 2, y: (ink[1] + ink[3]) / 2, r: Math.max(h * 0.9, 20), ok: draws.every(d => d.check.ok) };
  }
  band(s, instant, ms = LINE_MS) {
    const { x1, y1, x2, y2 } = s.line;
    const l = svg('line', { x1, y1, x2, y2, class: s.check.ok ? 'holds' : 'fails' });
    this.bands.append(l);
    const len = Math.hypot(x2 - x1, y2 - y1);
    l.setAttribute('stroke-dasharray', `${len} ${len}`);
    if (instant) return Promise.resolve();
    return l.animate([{ strokeDashoffset: len }, { strokeDashoffset: 0 }], { duration: ms, easing: 'cubic-bezier(.23,1,.32,1)', fill: 'backwards' }).finished.catch(() => {});
  }
  svgRing(r, instant, ms = RING_MS) {
    const c = svg('circle', { cx: r.x, cy: r.y, r: r.r, class: r.ok ? 'holds' : 'fails' });
    c.style.opacity = 1;
    this.bands.append(c);
    const len = 2 * Math.PI * r.r;
    c.setAttribute('stroke-dasharray', `${len} ${len}`);
    c.setAttribute('transform', `rotate(-90 ${r.x} ${r.y})`);
    if (instant) return Promise.resolve();
    return c.animate([{ strokeDashoffset: len }, { strokeDashoffset: 0 }], { duration: ms, easing: 'ease-out', fill: 'backwards' }).finished.catch(() => {});
  }

  // ---- partial: no page image, so the block's own image is shown flat where the sheet would be
  hasBlockImage() { return this.store.blocks.size && [...this.store.blocks.values()].some(b => b.p === this.page && b.bi); }
  setPartial(on) {
    this.partial = on;
    this.root.classList.toggle('partial', on);
    const bs = document.body.dataset;
    if (on) bs.state = 'partial'; else if (bs.state === 'partial' && !this.forcePartial) bs.state = 'ready';
    this.flatEl.hidden = !on;
    if (on) { this.setLabel('The page image is not available. The block of the scan is shown flat.'); this.updateFlat(); }
    else this.flatEl.replaceChildren();
  }
  updateFlat() {
    const el = this.flatEl, a = this.flatArgs;
    el.replaceChildren();
    if (!a || !el.clientWidth) return;
    const { v, draws } = a, blk = this.store.block(v);
    if (!blk || !blk.bi || !blk.x) { const p = document.createElement('p'); p.textContent = 'No image of this block is available.'; el.append(p); return; }
    const { bi } = blk, W = el.clientWidth, H = el.clientHeight;
    const k = Math.min(0.75, H / bi.h);
    const mx = bi.w / (blk.x[2] - blk.x[0]), my = bi.h / (blk.x[3] - blk.x[1]);
    const X = x => (x - blk.x[0]) * mx, Y = y => (y - blk.x[1]) * my;
    const cx = v.ix ? (v.ix[0] + v.ix[2]) / 2 : v.x ? X((v.x[0] + v.x[2]) / 2) : 0;
    const tx = bi.w * k <= W ? (W - bi.w * k) / 2 : Math.min(0, Math.max(W - bi.w * k, W / 2 - cx * k));
    const pan = document.createElement('div');
    pan.className = 'fb-pan';
    pan.style.cssText = `width:${bi.w}px;height:${bi.h}px;transform:translate(${tx}px,${(H - bi.h * k) / 2}px) scale(${k})`;
    const img = document.createElement('img');
    img.alt = ''; img.src = bi.img; img.width = bi.w; img.height = bi.h;
    const o = svg('svg', { viewBox: `0 0 ${bi.w} ${bi.h}`, width: bi.w, height: bi.h, class: 'fb-svg', 'aria-hidden': 'true' });
    for (const d of draws) {
      if (!d.line) continue;
      const thick = d.axis === 'row' ? (v.x ? (v.x[3] - v.x[1]) * my : 48) : (v.x ? (v.x[2] - v.x[0]) * mx : 150);
      const l = svg('line', { x1: X(d.line.x1), y1: Y(d.line.y1), x2: X(d.line.x2), y2: Y(d.line.y2), class: d.ok ? 'holds' : 'fails' });
      l.style.strokeWidth = thick;
      o.append(l);
    }
    for (const j of this.store.byPage.get(blk.p) || []) {
      const q = this.store.values[j];
      if (q.b !== blk.id || !q.x) continue;
      const r = svg('rect', { x: X(q.x[0]), y: Y(q.x[1]), width: (q.x[2] - q.x[0]) * mx, height: (q.x[3] - q.x[1]) * my, class: 'fb-hit' });
      r.addEventListener('click', () => this.onPick(j));
      o.append(r);
    }
    if (v.x) {
      const box = v.ix || [X(v.x[0]), Y(v.x[1]), X(v.x[2]), Y(v.x[3])];
      const ring = svg('path', { d: v.ix ? loopPath(box, 8 / k) : boxPath(box, 4 / k), class: 'fb-ring ' + (draws.every(d => d.ok) ? 'holds' : 'fails') });
      ring.style.strokeWidth = 2.5 / k;
      o.append(ring);
    }
    pan.append(img, o);
    el.append(pan);
  }

  // ---- flat and tilted
  setFlat(f, animate = true) {
    this.flat = f;
    if (!this.pg) return;
    const keep = { ...this.P };
    this.base = this.fit();
    const P = this.target();
    this.setP(keep);
    this.go(P, animate && !this.reduced ? FLAT_MS : 0);
    this.pump(FLAT_MS + 100);
  }

  // ---- the sheet leans toward the pointer, by at most 3 degrees
  watchPointer() {
    const t = this.lean;
    this.viewport.addEventListener('pointermove', e => {
      if (e.pointerType !== 'mouse') return;
      const b = this.viewport.getBoundingClientRect();
      const nx = ((e.clientX - b.left) / b.width) * 2 - 1, ny = ((e.clientY - b.top) / b.height) * 2 - 1;
      t.tx = -nx * LEAN_MAX; t.ty = ny * LEAN_MAX;
      this.tick();
    });
    this.viewport.addEventListener('pointerleave', () => { t.tx = 0; t.ty = 0; this.tick(); });
  }
  tick() {
    const t = this.lean;
    if (t.raf) return;
    const step = () => {
      t.x += (t.tx - t.x) * 0.12; t.y += (t.ty - t.y) * 0.12;
      const done = Math.abs(t.tx - t.x) < 0.01 && Math.abs(t.ty - t.y) < 0.01;
      if (done) { t.x = t.tx; t.y = t.ty; }
      this.leanEl.style.transform = `rotateX(${t.y}deg) rotateY(${t.x}deg)`;
      this.updateLeader();
      t.raf = done ? 0 : requestAnimationFrame(step);
    };
    t.raf = requestAnimationFrame(step);
  }
}

// The loupe: the scan itself around the selected value, from the block's own 300 dpi image.
import { loopPath, boxPath } from './ring.js';
const SVGNS = 'http://www.w3.org/2000/svg';
const S0 = 1.25, CLEAR = 10, ROW_PAD = 8, FADE_MS = 150, AIR = 8, RING_PX = 2.5, RING_MS = 180;
const TAG_H = 22, TAG_GAP = 5, LOOP_BELOW = 10;   // the tag, its distance from the ring, and how far the loop reaches below the digits (block px)
// scale tiers tried in turn when the view is fitted to column edges: [smallest, largest, the row-label column must be whole]
const TIERS = [[1.0, 1.6, true], [0.8, 1.9, true], [1.0, 1.6, false], [0.8, 1.9, false]];
const EDGE_AIR = 14;   // the loop needs this much clear paper (block pixels) between the digits and the view's edge

const svg = (tag, attrs = {}) => {
  const e = document.createElementNS(SVGNS, tag);
  for (const k in attrs) e.setAttribute(k, attrs[k]);
  return e;
};
const fmt = n => (n === null || n === undefined ? 'none' : Number(n).toLocaleString('en-US'));

export class Loupe {
  constructor({ root, view, note }, { onPick, reduced = false }) {
    this.root = root; this.view = view; this.note = note; this.onPick = onPick; this.reduced = reduced;
    this.layer = null; this.last = null; this.ringEl = null; this.token = 0; this.tagEl = null; this.peekEl = null;
  }
  get W() { return this.view.clientWidth; }
  get H() { return this.view.clientHeight; }

  clear() {
    this.last = null; this.ringEl = null; this.peekEl = null; this.tagEl = null;
    for (const l of this.view.querySelectorAll('.lp-layer')) l.remove();
    this.layer = null; this.note.hidden = true;
  }

  // the part of the block image a value takes: [x0, x1, y0, y1] in block-image pixels
  extent(store, blk, v, layer) {
    const mx = blk.bi.w / (blk.x[2] - blk.x[0]), my = blk.bi.h / (blk.x[3] - blk.x[1]);
    if (v.ix) return [v.ix[0], v.ix[2], v.ix[1], v.ix[3]];
    let b = v.x;
    if (!b) {
      const sib = store.values.find(o => o.p === v.p && o.b === v.b && o.c === v.c && o.x);
      if (sib) return [(sib.x[0] - blk.x[0]) * mx, (sib.x[2] - blk.x[0]) * mx, layer.top, layer.top];
      return [0, 0, layer.top, layer.top];
    }
    return [(b[0] - blk.x[0]) * mx, (b[2] - blk.x[0]) * mx, (b[1] - blk.x[1]) * my, (b[3] - blk.x[1]) * my];
  }

  // where the pan sits: the view starts and ends on column edges (no figure or label cut in half), shows the row-label
  // column whole whenever it shows any of it, and keeps the value, its loop and its tag in view
  place(layer, ext) {
    const { bi } = layer.blk, W = this.W, H = this.H, E = layer.edges, lr = layer.labelRight;
    const [a, b, ya, yb] = ext, cx = (a + b) / 2;
    let S = S0, tx = null;
    outer: for (const [smin, smax, whole] of TIERS) {
      let best = null;
      for (const i of E) {
        if (whole && i > 0 && i < lr - 2) continue;
        for (const j of E) {
          if (j <= i + 40) continue;
          const sc = W / (j - i);
          if (sc < smin || sc > smax || a < i + EDGE_AIR || b > j - EDGE_AIR) continue;
          const score = Math.abs((i + j) / 2 - cx) + Math.abs(sc - S0) * 160;
          if (!best || score < best.score) best = { sc, left: i, score };
        }
      }
      if (best) { S = best.sc; tx = -best.left * S; break outer; }
    }
    if (tx === null) {   // no fit: the value centred, never past the block's own ends
      tx = W / 2 - cx * S;
      tx = Math.max(Math.min(tx, 0), Math.min(0, W - bi.w * S));
    }
    let ty = CLEAR - layer.top * S;   // 10 px of clear paper above the block's first row
    if (bi.h * S + ty < H && bi.h * S > H) ty = H - bi.h * S;
    const need = (yb + LOOP_BELOW) * S + TAG_GAP + TAG_H + 2;   // the value's loop and the tag hanging under it
    if (ty + need > H) ty = H - need;
    if (ty + ya * S < 4) ty = 4 - ya * S;
    return { S, tx, ty };
  }
  apply(layer, p) {
    layer.S = p.S; layer.tx = p.tx; layer.ty = p.ty;
    layer.pan.style.transform = `translate(${p.tx}px, ${p.ty}px) scale(${p.S})`;
  }

  // draws: [{line (page-image pixels), ok}]; animate: slide and fade, else change at once; extra: {tag, other}
  // a ring that waits to be drawn on (reveal) when the selection is animated
  show(store, i, draws, animate = true, extra = {}) {
    const v = store.values[i];
    const blk = store.block(v);
    this.last = { store, i, draws, extra };
    if (!blk || !blk.bi || !blk.x) { this.clear(); this.last = { store, i, draws, extra }; this.note.hidden = !!v.x; return; }
    this.note.hidden = !!v.x;
    const key = `${blk.p}:${blk.id}`;
    const same = this.layer && this.layer.key === key;
    let layer = this.layer;
    if (!same) {
      const old = this.layer;
      layer = this.layer = this.build(store, blk, key);
      this.view.append(layer.el);
      this.fadeIn(layer, animate);
      if (old) this.fadeOut(old, animate);
    }
    const ext = this.extent(store, blk, v, layer);
    layer.pan.classList.toggle('slide', same && animate);
    layer.ext = ext;
    this.apply(layer, this.place(layer, ext));
    this.paint(layer, store, blk, v, draws, extra, animate && !this.reduced);
    this.moveTag(layer, v, same && animate);
  }

  fadeIn(layer, animate) {
    const done = () => { layer.el.classList.add('in'); };
    const img = layer.img;
    if (!animate) { layer.el.classList.add('instant'); done(); }
    else if (img.complete && img.naturalWidth) requestAnimationFrame(() => requestAnimationFrame(done));
    else { img.onload = done; img.onerror = done; }
  }
  fadeOut(old, animate) {
    old.el.classList.remove('in');
    if (animate) setTimeout(() => old.el.remove(), FADE_MS + 60); else old.el.remove();
  }

  // a finding with no place on the sheet: the group's crop, flat, with no ring
  showCrop(src, alt, animate = true) {
    const old = this.layer;
    this.last = null; this.ringEl = null; this.peekEl = null;
    if (this.tagEl) this.tagEl.classList.remove('on');
    this.note.hidden = true;
    const el = document.createElement('div');
    el.className = 'lp-layer lp-cropbox';
    const img = document.createElement('img');
    img.className = 'lp-crop'; img.alt = alt || ''; img.decoding = 'async'; img.src = src;
    el.append(img);
    const layer = this.layer = { key: `crop:${src}`, el, img, crop: true };
    this.view.append(el);
    this.fadeIn(layer, animate);
    if (old) this.fadeOut(old, animate);
  }

  build(store, blk, key) {
    const { bi } = blk;
    const el = document.createElement('div');
    el.className = 'lp-layer';
    const pan = document.createElement('div');
    pan.className = 'lp-pan';
    pan.style.width = `${bi.w}px`; pan.style.height = `${bi.h}px`;
    const img = document.createElement('img');
    img.alt = ''; img.decoding = 'async'; img.width = bi.w; img.height = bi.h;
    img.src = bi.img;
    const s = svg('svg', { viewBox: `0 0 ${bi.w} ${bi.h}`, width: bi.w, height: bi.h, class: 'lp-svg' });
    pan.append(img, s);
    el.append(pan);
    const all = (store.byPage.get(blk.p) || []).map(j => store.values[j]).filter(o => o.b === blk.id && o.x);
    const rows = all.filter(o => !store.isTotal(o));
    const mx = bi.w / (blk.x[2] - blk.x[0]), m = bi.h / (blk.x[3] - blk.x[1]);
    // the ruled line above the first row when the build found it, else a little above the first cell
    const top = bi.rt != null ? bi.rt - 1 : rows.length ? (Math.min(...rows.map(o => o.x[1])) - blk.x[1]) * m - ROW_PAD : 0;
    // column edges: where the cells and printed totals begin and end, in block-image pixels; the label column is what lies left of them
    const raw = [0, bi.w];
    for (const o of all) raw.push((o.x[0] - blk.x[0]) * mx, (o.x[2] - blk.x[0]) * mx);
    raw.sort((p, q) => p - q);
    const edges = [];
    for (const e of raw) { if (!edges.length || e - edges[edges.length - 1] > 6) edges.push(Math.max(0, Math.min(bi.w, e))); }
    const first = all.length ? Math.min(...all.map(o => (o.x[0] - blk.x[0]) * mx)) : 0;
    return { key, blk, el, pan, img, svg: s, top: Math.max(0, top), S: S0, tx: 0, ty: 0, edges, labelRight: first > 30 ? first : 0, ext: null };
  }

  paint(layer, store, blk, v, draws, extra, pending = false) {
    const { svg: s } = layer, { bi } = blk, S = layer.S;
    const mx = bi.w / (blk.x[2] - blk.x[0]), my = bi.h / (blk.x[3] - blk.x[1]);
    const X = x => (x - blk.x[0]) * mx, Y = y => (y - blk.x[1]) * my;
    s.replaceChildren();
    for (const d of draws) {
      if (!d.line) continue;
      const { x1, y1, x2, y2 } = d.line;
      // a band is one cell thick: the printed figure sits low in its cell, so a thin line would miss it
      const thick = d.axis === 'row' ? (v.x ? (v.x[3] - v.x[1]) * my : 48) : (v.x ? (v.x[2] - v.x[0]) * mx : 150);
      s.append(svg('line', { x1: X(x1), y1: Y(y1), x2: X(x2), y2: Y(y2), 'stroke-width': thick, class: d.ok ? 'holds' : 'fails' }));
    }
    for (const j of store.byPage.get(blk.p) || []) {
      const o = store.values[j];
      if (o.b !== blk.id || !o.x) continue;
      const r = svg('rect', { x: X(o.x[0]), y: Y(o.x[1]), width: (o.x[2] - o.x[0]) * mx, height: (o.x[3] - o.x[1]) * my, class: 'lp-hit' });
      r.dataset.i = j;
      r.addEventListener('click', () => this.onPick(j));
      s.append(r);
    }
    // the cell where the file put the value (a wrong column): outline only
    const other = extra.other !== undefined ? store.values[extra.other] : null;
    if (other && other.x && other.b === blk.id && other.p === blk.p) {
      const o = svg('rect', { x: X(other.x[0]) + 2, y: Y(other.x[1]) + 2, width: (other.x[2] - other.x[0]) * mx - 4, height: (other.x[3] - other.x[1]) * my - 4, class: 'lp-ring2' });
      o.style.strokeWidth = 1.5 / S;
      s.append(o);
    }
    this.ringEl = null; this.peekEl = null;
    if (v.x) {
      // a pencil loop round the printed figure (its ink box) with 8 px of air; without one, round the cell's box
      const ok = draws.every(d => d.ok);
      const box = v.ix || [X(v.x[0]), Y(v.x[1]), X(v.x[2]), Y(v.x[3])];
      const ring = svg('path', { d: v.ix ? loopPath(box, AIR / S) : boxPath(box), pathLength: 1,
                                 class: 'lp-ring ' + (ok ? 'holds' : 'fails') });
      ring.style.strokeWidth = RING_PX / S;
      if (pending) { ring.style.strokeDasharray = '1 1'; ring.style.strokeDashoffset = 1; }
      s.append(ring);
      this.ringEl = ring;
    }
    this.tagText = extra.tag === undefined ? null : extra.tag;
  }

  // the paper tag that hangs from the ring: under it, never over the digits
  moveTag(layer, v, slide) {
    if (!this.tagText || !v.x) { if (this.tagEl) this.tagEl.classList.remove('on'); return; }
    if (!this.tagEl) {
      this.tagEl = document.createElement('div');
      this.tagEl.className = 'lp-tag';
      this.tagEl.setAttribute('aria-hidden', 'true');
    }
    const t = this.tagEl;
    if (!t.isConnected) this.view.append(t);
    t.textContent = this.tagText;
    t.classList.toggle('slide', !!slide);
    const [a, b, , yb] = layer.ext, S = layer.S;
    const w = t.offsetWidth;
    // hangs from the loop's lower left, wholly to the left of the digits: figures sit at the right of their cells, so the
    // paper under and left of the loop is clear, and the figure of the row below is not covered
    const left = Math.max(4, Math.min(this.W - w - 4, layer.tx + a * S - 2 - w));
    const topPx = layer.ty + (yb + LOOP_BELOW) * S + TAG_GAP;
    t.style.transform = `translate(${left}px, ${topPx}px)`;
    t.classList.toggle('on', !this.ringEl || this.ringEl.style.strokeDashoffset !== '1');
  }

  // draws the ring on, from its top left, once the sums are drawn
  reveal(animate = true, ms = RING_MS) {
    const r = this.ringEl;
    const tag = () => { if (this.tagEl && this.tagText) this.tagEl.classList.add('on'); };
    if (!r || r.style.strokeDashoffset !== '1') { tag(); return Promise.resolve(); }
    if (!animate || this.reduced) { r.style.strokeDashoffset = ''; r.style.strokeDasharray = ''; tag(); return Promise.resolve(); }
    const done = () => { r.style.strokeDashoffset = ''; r.style.strokeDasharray = ''; tag(); };
    return r.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: ms, easing: 'ease-out', fill: 'forwards' })
      .finished.then(done, done);
  }

  // the keyboard is on another value of the sheet: show it here too, without selecting it (i null: back to the selection)
  peek(store, i) {
    const l = this.layer;
    if (!l || l.crop) return;
    if (this.peekEl) { this.peekEl.remove(); this.peekEl = null; }
    const sel = this.last && store.values[this.last.i];
    const v = i === null || i === undefined ? sel : store.values[i];
    if (!v || v.p !== l.blk.p || v.b !== l.blk.id) return;
    l.pan.classList.add('slide');
    const away = !(i === null || i === undefined || i === (this.last && this.last.i));
    const ext = this.extent(store, l.blk, v, l);
    l.ext = ext;
    this.apply(l, this.place(l, ext));
    if (this.tagEl) {
      this.tagEl.classList.toggle('slide', true);
      if (away) this.tagEl.classList.remove('on'); else { this.moveTag(l, v, true); this.tagEl.classList.add('on'); }
    }
    if (!away || !v.x) return;
    const { blk } = l, { bi } = blk, S = l.S;
    const mx = bi.w / (blk.x[2] - blk.x[0]), my = bi.h / (blk.x[3] - blk.x[1]);
    const b = v.ix ? [v.ix[0] - 3, v.ix[1] - 3, v.ix[2] + 3, v.ix[3] + 3]
                   : [(v.x[0] - blk.x[0]) * mx, (v.x[1] - blk.x[1]) * my, (v.x[2] - blk.x[0]) * mx, (v.x[3] - blk.x[1]) * my];
    const g = svg('g', { class: 'lp-peek' });
    for (const [cls, w] of [['dark', 4], ['light', 2]]) {
      const r = svg('rect', { x: b[0], y: b[1], width: b[2] - b[0], height: b[3] - b[1], class: cls });
      r.style.strokeWidth = w / S;
      g.append(r);
    }
    l.svg.append(g);
    this.peekEl = g;
  }

  // the window changed size: put the pan back where it belongs, at once
  relayout() {
    const l = this.layer;
    if (!l || l.crop || !this.last) return;
    l.pan.classList.remove('slide');
    if (this.tagEl) this.tagEl.classList.remove('slide');
    const { store, i } = this.last, v = store.values[i];
    const ext = this.extent(store, l.blk, v, l);
    l.ext = ext;
    this.apply(l, this.place(l, ext));
    this.paint(l, store, l.blk, v, this.last.draws, this.last.extra, false);
    this.moveTag(l, v, false);
  }
}
// The adding-machine tape: prints a sum line by line, ending on the printed total.
import { fmt } from './data.js';

const MAX_TOTAL_MS = 900, STEP_MS = 60;
const termLabel = (c, t) => (c.k === 'col' ? t.r : c.k === 'grand_row' ? t.c : `Precinct ${t.c}`);
const heading = c => c.k === 'col' ? `Down the column · precinct ${c.y}` : c.k === 'row' ? `Across the row · ${c.y}`
  : c.k === 'grand_row' ? 'Down the row totals' : 'Across the small totals';
const kindLabel = (kind, v) => (kind === 'col' ? v.r : kind === 'row' ? `Precinct ${v.c}` : kind === 'grand_row' ? v.c : `Precinct ${v.c}`);
// a short heading for a deciding sum; its whole name is in the card under "Decided by"
const sumHeading = (s, f, store) => {
  const v = f.ref === undefined ? null : store.values[f.ref];
  return s.kind === 'col' ? `Down the column${v && !store.isTotal(v) ? ` · precinct ${v.c}` : f.precinct ? ` · precinct ${f.precinct}` : ''}`
    : s.kind === 'row' ? `Across the row${v && v.r ? ` · ${v.r}` : ''}`
    : s.kind === 'grand_row' ? 'Down the row totals' : 'Across the small totals';
};
const val = n => (n === undefined || n === null ? '—' : fmt(n));
const cap = s => (s ? s[0].toUpperCase() + s.slice(1) : s);

export function termLines(store, c) {
  const terms = store.termsOf(c);
  const row = t => ({ label: termLabel(c, t), fig: fmt(t.v), i: t.i });
  if (terms.length <= 5) return terms.map(row);
  return [...terms.slice(0, 3).map(row), { label: `… ${terms.length - 4} more`, fig: '', more: true }, row(terms[terms.length - 1])];
}

// a fine zigzag along the lower edge, 6 px deep
function tornEdge() {
  const pts = ['0 0', '100% 0', '100% calc(100% - 6px)'];
  const n = 50;
  for (let i = n - 1; i >= 0; i--) pts.push(`${(i * 100 / n).toFixed(2)}% ${i % 2 ? 'calc(100% - 6px)' : '100%'}`);
  return `polygon(${pts.join(', ')})`;
}

function el(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}
function line(label, fig, cls, pick) {
  const d = el('div', 'ln' + (cls ? ' ' + cls : ''));
  d.append(el('span', '', label), el('span', '', fig));
  if (!pick) return d;
  // a term line is a button: it selects its value
  const b = el('button', 'ln pick' + (cls ? ' ' + cls : ''));
  b.type = 'button';
  b.append(...d.children);
  b.addEventListener('click', pick);
  return b;
}

// the lines of a finding's sum, both ways: [{label, file, scan, diff, ref, more}]. `own` is the value the finding sits on.
// Terms hold the scan's value (the ledger's); the file's column swaps in the file's value at the term that differs.
export function pairLines(store, f, s) {
  const own = f.ref;
  const rows = s.terms.map(([ref, val]) => {
    const v = ref === null || ref === undefined ? null : store.values[ref];
    const diff = own !== undefined && ref === own;
    return { label: v ? kindLabel(s.kind, v) : '…', scan: fmt(val), file: diff ? (f.file === undefined ? '—' : fmt(f.file)) : fmt(val), diff, ref: v ? ref : undefined };
  });
  if (!rows.some(r => r.diff) && f.kind === 'extra_row' && f.file !== undefined) {
    // a row only the file has: no term of the scan's sum is it
    rows.push({ label: 'file only', scan: '—', file: fmt(f.file), diff: true });
  }
  if (rows.length <= 6) return rows;
  const keep = new Set([0, 1, rows.length - 1]);
  rows.forEach((r, i) => { if (r.diff) keep.add(i); });
  const out = []; let gap = 0;
  rows.forEach((r, i) => {
    if (keep.has(i)) { if (gap) { out.push({ label: `… ${gap} more`, scan: '', file: '', more: true }); gap = 0; } out.push(r); } else gap++;
  });
  return out;
}

export class Tape {
  constructor(root, reduced, onPick = () => {}) {
    this.onPick = onPick; this.root = root; this.reduced = reduced; this.timers = [];
    root.style.clipPath = tornEdge();
    this.clear();
  }
  stop() { this.timers.forEach(clearTimeout); this.timers = []; }
  // keeps its height while empty, so the panel under it does not jump
  clear() { this.stop(); this.root.style.minHeight = `${this.root.offsetHeight}px`; this.root.replaceChildren(); }
  // a finding: each deciding sum printed twice side by side (the public file's value, the scan's value), then the other
  // sums through the value, quieter. Steps are rows of the pair, 60 ms each, as for a single sum.
  printFinding(store, f, others, animate = true, totalMs = MAX_TOTAL_MS) {
    this.stop();
    this.root.replaceChildren();
    this.root.style.minHeight = '';
    this.root.classList.add('two');
    const steps = [];
    const mk = (box, node) => { node.style.visibility = 'hidden'; box.append(node); steps.push(node); };
    const pair = (cls, a, b, pick) => {
      const row = el('div', 'pair' + (cls ? ' ' + cls : ''));
      for (const side of [a, b]) {
        const cell = el('div', 'ln' + (side.diff ? ' diff' : '') + (side.cls ? ' ' + side.cls : ''));
        const lab = el('span', '', side.label);
        if (side.diff) lab.append(el('span', 'sr', ' (differs)'));
        cell.append(lab, el('span', '', side.fig));
        if (pick && side.ref !== undefined) {
          const bt = el('button', 'ln pick' + (side.diff ? ' diff' : ''));
          bt.type = 'button'; bt.append(...cell.children);
          bt.addEventListener('click', () => this.onPick(side.ref));
          row.append(bt);
        } else row.append(cell);
      }
      return row;
    };
    if (!f.sums.length) this.root.append(el('p', 'empty', 'No printed sum was recorded through this value.'));
    for (const s of f.sums) {
      const box = el('div', 'sum two');
      box.append(el('h3', '', sumHeading(s, f, store)));
      const heads = el('div', 'pair heads');
      heads.append(el('h4', '', "With the public file's value"), el('h4', '', "With the scan's value"));
      box.append(heads);
      for (const l of pairLines(store, f, s)) {
        const cls = l.more ? 'more' : '';
        mk(box, pair(cls, { label: l.label, fig: l.file, diff: l.diff, ref: l.ref, cls }, { label: l.label, fig: l.scan, diff: l.diff, ref: l.ref, cls }, true));
      }
      mk(box, pair('rule', { label: 'adds to', fig: fmt(s.with_file) }, { label: 'adds to', fig: fmt(s.with_scan) }));
      // when the value the finding sits on is this sum's printed total, the file's column carries the file's value there
      const ownIsPrinted = f.ref !== undefined && store.isTotal(store.values[f.ref]) && !s.terms.some(t => t[0] === f.ref);
      mk(box, pair('', { label: 'printed total', fig: ownIsPrinted ? val(f.file) : fmt(s.printed), diff: ownIsPrinted },
                       { label: 'printed total', fig: fmt(s.printed), diff: ownIsPrinted }));
      const res = el('div', 'pair res2');
      for (const holds of [s.holds_file, s.holds_scan]) res.append(el('div', 'res ' + (holds ? 'holds' : 'fails'), holds ? '✓ matches' : '✗ does not match'));
      mk(box, res);
      this.root.append(box);
    }
    if (others.length) {
      const more = el('div', 'others');
      more.append(el('h3', '', 'Other printed sums through this value'));
      this.root.append(more);
      for (const { check: c } of others) {
        const box = el('div', 'sum quiet');
        box.append(el('h3', '', heading(c)));
        const sub = el('div', 'one');
        for (const l of termLines(store, c)) sub.append(line(l.label, l.fig, l.more ? 'more' : '', null));
        sub.append(line('adds to', fmt(c.co), 'rule'), line('printed total', fmt(c.pr)),
                   el('div', 'res ' + (c.ok ? 'holds' : 'fails'), c.ok ? '✓ matches' : '✗ does not match'));
        box.append(sub);
        mk(more, box);
      }
    }
    if (!animate || this.reduced) { steps.forEach(s => (s.style.visibility = '')); return; }
    const step = Math.min(STEP_MS, totalMs / steps.length);
    steps.forEach((s, i) => this.timers.push(setTimeout(() => { s.style.visibility = ''; }, i * step)));
  }

  // sums: [{check, axis}]; the lines are built first, then shown one by one
  print(store, sums, animate = true, totalMs = MAX_TOTAL_MS) {
    this.stop();
    this.root.replaceChildren();
    this.root.style.minHeight = '';
    this.root.classList.remove('two');
    const steps = [];
    if (!sums.length) { this.root.append(el('p', 'empty', 'No printed sum was recorded through this value.')); return; }
    for (const { check: c } of sums) {
      const box = el('div', 'sum');
      const h = el('h3', '', heading(c));
      box.append(h);
      const mk = (node) => { node.style.visibility = 'hidden'; box.append(node); steps.push(node); };
      for (const l of termLines(store, c)) mk(line(l.label, l.fig, l.more ? 'more' : '', l.i === undefined ? null : () => this.onPick(l.i)));
      mk(line('adds to', fmt(c.co), 'rule'));
      mk(line('printed total', fmt(c.pr)));
      mk(el('div', 'res ' + (c.ok ? 'holds' : 'fails'), c.ok ? '✓ matches' : '✗ does not match'));
      this.root.append(box);
    }
    if (!animate || this.reduced) { steps.forEach(s => (s.style.visibility = '')); return; }
    const step = Math.min(STEP_MS, totalMs / steps.length);
    steps.forEach((s, i) => this.timers.push(setTimeout(() => { s.style.visibility = ''; }, i * step)));
  }
}
// The findings: the card, the list with its filters, the run numbers and the crop and evidence dialogs.
import { fmt, KIND, KINDS, STATUS, STATUSES, PART, UNCONFIRMED } from './data.js';

const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; };
const hid = e => { e.setAttribute('aria-hidden', 'true'); return e; };
const cap = s => (s ? s[0].toUpperCase() + s.slice(1) : s);
const val = n => (n === undefined || n === null ? '—' : fmt(n));
const valWords = n => (n === undefined || n === null ? 'none' : fmt(n));
const plural = (n, one, many) => `${fmt(n)} ${n === 1 ? one : many}`;
export const VIRTUAL_ABOVE = 200;   // rows; more than this and only the rows near the viewport are in the page

// the other finding of the group that holds the value this one's scan has (a swap): where the file put it
export function siblingOf(store, f) {
  const g = store.groupById.get(f.group);
  if (!g || f.scan === undefined || f.file === undefined) return null;
  const sibs = g.findings.map(id => store.itemById.get(id)).filter(o => o && o.id !== f.id && (o.precinct !== f.precinct || o.part !== f.part));
  return sibs.find(o => o.file === f.scan && o.scan === f.file) || null;
}

// the one plain sentence for what kind of slip this is
export function sentence(store, f) {
  const sib = siblingOf(store, f);
  const v = f.ref === undefined ? null : store.values[f.ref];
  if (f.scan === undefined && (f.kind === 'wrong_column' || f.kind === 'wrong_precinct')) {
    return `The file has ${val(f.file)} under precinct ${f.precinct}${f.part && f.part !== 'votes' ? `, ${PART[f.part]}` : ''}. The scan has no value there.`;
  }
  switch (f.kind) {
    case 'wrong_column':
      return `On the scan this vote is under ${v ? v.r : PART[f.part] || 'one column'}. ` +
        (sib ? `The file has it under ${PART[sib.part] || 'another column'}.` : 'The file has it under another column.');
    case 'wrong_precinct':
      return `On the scan this value is under precinct ${f.precinct}. ` +
        (sib ? `The file has it under precinct ${sib.precinct}.` : 'The file has it under another precinct.');
    case 'missing_row': return 'The scan has this value. The file has no row for it.';
    case 'extra_row': return 'The file has a row here that is not on the scan.';
    case 'file_row_fails_own_total': return "The parts of this row in the file do not add to the row's own total in the file.";
    default: return 'The file and the scan give different numbers for this one value.';
  }
}

// the line above the loupe: page, contest, row label, precinct
export const contextLine = (store, f) => [f.page ? `Page ${f.page}` : null, f.office, f.row, f.precinct ? `precinct ${f.precinct}` : null].filter(Boolean).join(' · ');

export function renderFindingCard(root, store, f, { onCrop, onEvidence }) {
  root.replaceChildren();
  root.className = 'card finding';
  root.setAttribute('aria-label', 'Selected finding');
  const kind = KIND[f.kind] || { word: f.kind, glyph: '' };
  const st = STATUS[f.status] || { word: f.status, glyph: '', line: '' };
  root.append(el('p', 'eyebrow', [f.office, f.page ? `page ${f.page}` : null].filter(Boolean).join(' · ')));
  root.append(el('h2', '', [f.row, f.precinct ? `precinct ${f.precinct}` : null, PART[f.part]].filter(Boolean).join(' · ')));
  const pair = el('div', 'two-values');
  for (const [label, n, cls] of [['Public file', f.file, 'file'], ['Scan', f.scan, 'scan']]) {
    const d = el('div', 'one ' + cls);
    d.append(el('span', 'lab', label), el('span', 'fig', val(n)));
    if (n === undefined || n === null) d.firstChild.after(Object.assign(el('span', 'sr', ': none')));
    pair.append(d);
  }
  root.append(pair);
  const k = el('p', 'kind');
  k.append(el('span', 'lab', 'Kind of slip'), el('span', 'kg', kind.glyph), el('span', 'kw', kind.word));
  k.querySelector('.kg').setAttribute('aria-hidden', 'true');
  root.append(k, el('p', 'sentence', sentence(store, f)));
  const dec = el('div', 'decided');
  dec.append(el('span', 'lab', 'Decided by'));
  if (f.sums.length) {
    const ul = el('ul');
    for (const s of f.sums) ul.append(el('li', '', cap(s.name)));
    dec.append(ul);
  } else dec.append(el('span', '', 'No printed sum was recorded for this value.'));
  root.append(dec);
  const status = el('p', 'status ' + (f.status === 'settled_against_file' ? 'ok' : 'open'));
  status.append(hid(el('span', 'sg', st.glyph)), st.line);
  root.append(status);
  root.append(el('p', 'person', UNCONFIRMED));
  if (f.reread_disagrees) {
    root.append(el('p', 'how', `A closer look at this one value read ${val(f.reread_value)}. The printed sums decide.`));
  }
  const btns = el('div', 'btns');
  const crop = el('button', '', 'Open crop'), ev = el('button', '', 'Evidence file');
  crop.type = ev.type = 'button';
  crop.addEventListener('click', () => onCrop(f, crop));
  ev.addEventListener('click', () => onEvidence(f, ev));
  btns.append(crop, ev);
  root.append(btns);
}

// ---- the dialog: the group's crop with the sums in words, or the finding's evidence
export class Dialog {
  constructor(root) {
    this.root = root; this.title = root.querySelector('.dlg-title'); this.body = root.querySelector('.dlg-body');
    this.opener = null; this.evidence = null;
    root.querySelector('.dlg-close').addEventListener('click', () => root.close());
    root.addEventListener('close', () => { if (this.opener && this.opener.isConnected) this.opener.focus(); this.opener = null; });
    root.addEventListener('click', e => { if (e.target === root) root.close(); });   // a click on the backdrop
  }
  open(title, nodes, opener) {
    this.opener = opener || document.activeElement;
    this.title.textContent = title;
    this.body.replaceChildren(...nodes);
    if (!this.root.open) this.root.showModal();
    this.root.querySelector('.dlg-close').focus();
  }
  crop(store, f, opener) {
    const g = store.groupById.get(f.group);
    const nodes = [];
    if (g && g.crop) {
      const fig = el('figure', 'dlg-fig');
      const img = el('img');
      img.src = g.crop;
      img.alt = `The scan around ${f.row || 'the row'}, precinct ${f.precinct}, as cropped by the audit`;
      fig.append(img);
      nodes.push(fig);
    } else nodes.push(el('p', 'dlg-note', 'No crop was saved for this group.'));
    nodes.push(el('p', 'dlg-note', 'The scan is the source. Add the figures up yourself.'));
    for (const s of f.sums) {
      const d = el('div', '

    this.layer = null; this.note.hidden = true;
  }

  // the part of the block image a value takes: [x0, x1, y0, y1] in block-image pixels
  extent(store, blk, v, layer) {
    const mx = blk.bi.w / (blk.x[2] - blk.x[0]), my = blk.bi.h / (blk.x[3] - blk.x[1]);
    if (v.ix) return [v.ix[0], v.ix[2], v.ix[1], v.ix[3]];
    let b = v.x;
    if (!b) {
      const sib = store.values.find(o => o.p === v.p && o.b === v.b && o.c === v.c && o.x);
      if (sib) return [(sib.x[0] - blk.x[0]) * mx, (sib.x[2] - blk.x[0]) * mx, layer.top, layer.top];
      return [0, 0, layer.top, layer.top];
    }
    return [(b[0] - blk.x[0]) * mx, (b[2] - blk.x[0]) * mx, (b[1] - blk.x[1]) * my, (b[3] - blk.x[1]) * my];
  }

  // where the pan sits: the view starts and ends on column edges (no figure or label cut in half), shows the row-label
  // column whole whenever it shows any of it, and keeps the value, its loop and its tag in view
  place(layer, ext) {
    const { bi } = layer.blk, W = this.W, H = this.H, E = layer.edges, lr = layer.labelRight;
    const [a, b, ya, yb] = ext, cx = (a + b) / 2;
    let S = S0, tx = null;
    outer: for (const [smin, smax, whole] of TIERS) {
      let best = null;
      for (const i of E) {
        if (whole && i > 0 && i < lr - 2) continue;
        for (const j of E) {
          if (j <= i + 40) continue;
          const sc = W / (j - i);
          if (sc < smin || sc > smax || a < i + EDGE_AIR || b > j - EDGE_AIR) continue;
          const score = Math.abs((i + j) / 2 - cx) + Math.abs(sc - S0) * 160;
          if (!best || score < best.score) best = { sc, left: i, score };
        }
      }
      if (best) { S = best.sc; tx = -best.left * S; break outer; }
    }
    if (tx === null) {   // no fit: the value centred, never past the block's own ends
      tx = W / 2 - cx * S;
      tx = Math.max(Math.min(tx, 0), Math.min(0, W - bi.w * S));
    }
    let ty = CLEAR - layer.top * S;   // 10 px of clear paper above the block's first row
    if (bi.h * S + ty < H && bi.h * S > H) ty = H - bi.h * S;
    const need = (yb + LOOP_BELOW) * S + TAG_GAP + TAG_H + 2;   // the value's loop and the tag hanging under it
    if (ty + need > H) ty = H - need;
    if (ty + ya * S < 4) ty = 4 - ya * S;
    return { S, tx, ty };
  }
  apply(layer, p) {
    layer.S = p.S; layer.tx = p.tx; layer.ty = p.ty;
    layer.pan.style.transform = `translate(${p.tx}px, ${p.ty}px) scale(${p.S})`;
  }

  // draws: [{line (page-image pixels), ok}]; animate: slide and fade, else change at once; extra: {tag, other}
  // a ring that waits to be drawn on (reveal) when the selection is animated
  show(store, i, draws, animate = true, extra = {}) {
    const v = store.values[i];
    const blk = store.block(v);
    this.last = { store, i, draws, extra };
    if (!blk || !blk.bi || !blk.x) { this.clear(); this.last = { store, i, draws, extra }; this.note.hidden = !!v.x; return; }
    this.note.hidden = !!v.x;
    const key = `${blk.p}:${blk.id}`;
    const same = this.layer && this.layer.key === key;
    let layer = this.layer;
    if (!same) {
      const old = this.layer;
      layer = this.layer = this.build(store, blk, key);
      this.view.append(layer.el);
      this.fadeIn(layer, animate);
      if (old) this.fadeOut(old, animate);
    }
    const ext = this.extent(store, blk, v, layer);
    layer.pan.classList.toggle('slide', same && animate);
    layer.ext = ext;
    this.apply(layer, this.place(layer, ext));
    this.paint(layer, store, blk, v, draws, extra, animate && !this.reduced);
    this.moveTag(layer, v, same && animate);
  }

  fadeIn(layer, animate) {
    const done = () => { layer.el.classList.add('in'); };
    const img = layer.img;
    if (!animate) { layer.el.classList.add('instant'); done(); }
    else if (img.complete && img.naturalWidth) requestAnimationFrame(() => requestAnimationFrame(done));
    else { img.onload = done; img.onerror = done; }
  }
  fadeOut(old, animate) {
    old.el.classList.remove('in');
    if (animate) setTimeout(() => old.el.remove(), FADE_MS + 60); else old.el.remove();
  }

  // a finding with no place on the sheet: the group's crop, flat, with no ring
  showCrop(src, alt, animate = true) {
    const old = this.layer;
    this.last = null; this.ringEl = null; this.peekEl = null;
    if (this.tagEl) this.tagEl.classList.remove('on');
    this.note.hidden = true;
    const el = document.createElement('div');
    el.className = 'lp-layer lp-cropbox';
    const img = document.createElement('img');
    img.className = 'lp-crop'; img.alt = alt || ''; img.decoding = 'async'; img.src = src;
    el.append(img);
    const layer = this.layer = { key: `crop:${src}`, el, img, crop: true };
    this.view.append(el);
    this.fadeIn(layer, animate);
    if (old) this.fadeOut(old, animate);
  }

  build(store, blk, key) {
    const { bi } = blk;
    const el = document.createElement('div');
    el.className = 'lp-layer';
    const pan = document.createElement('div');
    pan.className = 'lp-pan';
    pan.style.width = `${bi.w}px`; pan.style.height = `${bi.h}px`;
    const img = document.createElement('img');
    img.alt = ''; img.decoding = 'async'; img.width = bi.w; img.height = bi.h;
    img.src = bi.img;
    const s = svg('svg', { viewBox: `0 0 ${bi.w} ${bi.h}`, width: bi.w, height: bi.h, class: 'lp-svg' });
    pan.append(img, s);
    el.append(pan);
    const all = (store.byPage.get(blk.p) || []).map(j => store.values[j]).filter(o => o.b === blk.id && o.x);
    const rows = all.filter(o => !store.isTotal(o));
    const mx = bi.w / (blk.x[2] - blk.x[0]), m = bi.h / (blk.x[3] - blk.x[1]);
    // the ruled line above the first row when the build found it, else a little above the first cell
    const top = bi.rt != null ? bi.rt - 1 : rows.length ? (Math.min(...rows.map(o => o.x[1])) - blk.x[1]) * m - ROW_PAD : 0;
    // column edges: where the cells and printed totals begin and end, in block-image pixels; the label column is what lies left of them
    const raw = [0, bi.w];
    for (const o of all) raw.push((o.x[0] - blk.x[0]) * mx, (o.x[2] - blk.x[0]) * mx);
    raw.sort((p, q) => p - q);
    const edges = [];
    for (const e of raw) { if (!edges.length || e - edges[edges.length - 1] > 6) edges.push(Math.max(0, Math.min(bi.w, e))); }
    const first = all.length ? Math.min(...all.map(o => (o.x[0] - blk.x[0]) * mx)) : 0;
    return { key, blk, el, pan, img, svg: s, top: Math.max(0, top), S: S0, tx: 0, ty: 0, edges, labelRight: first > 30 ? first : 0, ext: null };
  }

  paint(layer, store, blk, v, draws, extra, pending = false) {
    const { svg: s } = layer, { bi } = blk, S = layer.S;
    const mx = bi.w / (blk.x[2] - blk.x[0]), my = bi.h / (blk.x[3] - blk.x[1]);
    const X = x => (x - blk.x[0]) * mx, Y = y => (y - blk.x[1]) * my;
    s.replaceChildren();
    for (const d of draws) {
      if (!d.line) continue;
      const { x1, y1, x2, y2 } = d.line;
      // a band is one cell thick: the printed figure sits low in its cell, so a thin line would miss it
      const thick = d.axis === 'row' ? (v.x ? (v.x[3] - v.x[1]) * my : 48) : (v.x ? (v.x[2] - v.x[0]) * mx : 150);
      s.append(svg('line', { x1: X(x1), y1: Y(y1), x2: X(x2), y2: Y(y2), 'stroke-width': thick, class: d.ok ? 'holds' : 'fails' }));
    }
    for (const j of store.byPage.get(blk.p) || []) {
      const o = store.values[j];
      if (o.b !== blk.id || !o.x) continue;
      const r = svg('rect', { x: X(o.x[0]), y: Y(o.x[1]), width: (o.x[2] - o.x[0]) * mx, height: (o.x[3] - o.x[1]) * my, class: 'lp-hit' });
      r.dataset.i = j;
      r.addEventListener('click', () => this.onPick(j));
      s.append(r);
    }
    // the cell where the file put the value (a wrong column): outline only
    const other = extra.other !== undefined ? store.values[extra.other] : null;
    if (other && other.x && other.b === blk.id && other.p === blk.p) {
      const o = svg('rect', { x: X(other.x[0]) + 2, y: Y(other.x[1]) + 2, width: (other.x[2] - other.x[0]) * mx - 4, height: (other.x[3] - other.x[1]) * my - 4, class: 'lp-ring2' });
      o.style.strokeWidth = 1.5 / S;
      s.append(o);
    }
    this.ringEl = null; this.peekEl = null;
    if (v.x) {
      // a pencil loop round the printed figure (its ink box) with 8 px of air; without one, round the cell's box
      const ok = draws.every(d => d.ok);
      const box = v.ix || [X(v.x[0]), Y(v.x[1]), X(v.x[2]), Y(v.x[3])];
      const ring = svg('path', { d: v.ix ? loopPath(box, AIR / S) : boxPath(box), pathLength: 1,
                                 class: 'lp-ring ' + (ok ? 'holds' : 'fails') });
      ring.style.strokeWidth = RING_PX / S;
      if (pending) { ring.style.strokeDasharray = '1 1'; ring.style.strokeDashoffset = 1; }
      s.append(ring);
      this.ringEl = ring;
    }
    this.tagText = extra.tag === undefined ? null : extra.tag;
  }

  // the paper tag that hangs from the ring: under it, never over the digits
  moveTag(layer, v, slide) {
    if (!this.tagText || !v.x) { if (this.tagEl) this.tagEl.classList.remove('on'); return; }
    if (!this.tagEl) {
      this.tagEl = document.createElement('div');
      this.tagEl.className = 'lp-tag';
      this.tagEl.setAttribute('aria-hidden', 'true');
    }
    const t = this.tagEl;
    if (!t.isConnected) this.view.append(t);
    t.textContent = this.tagText;
    t.classList.toggle('slide', !!slide);
    const [a, b, , yb] = layer.ext, S = layer.S;
    const w = t.offsetWidth;
    // hangs from the loop's lower left, wholly to the left of the digits: figures sit at the right of their cells, so the
    // paper under and left of the loop is clear, and the figure of the row below is not covered
    const left = Math.max(4, Math.min(this.W - w - 4, layer.tx + a * S - 2 - w));
    const topPx = layer.ty + (yb + LOOP_BELOW) * S + TAG_GAP;
    t.style.transform = `translate(${left}px, ${topPx}px)`;
    t.classList.toggle('on', !this.ringEl || this.ringEl.style.strokeDashoffset !== '1');
  }

  // draws the ring on, from its top left, once the sums are drawn
  reveal(animate = true, ms = RING_MS) {
    const r = this.ringEl;
    const tag = () => { if (this.tagEl && this.tagText) this.tagEl.classList.add('on'); };
    if (!r || r.style.strokeDashoffset !== '1') { tag(); return Promise.resolve(); }
    if (!animate || this.reduced) { r.style.strokeDashoffset = ''; r.style.strokeDasharray = ''; tag(); return Promise.resolve(); }
    const done = () => { r.style.strokeDashoffset = ''; r.style.strokeDasharray = ''; tag(); };
    return r.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: ms, easing: 'ease-out', fill: 'forwards' })
      .finished.then(done, done);
  }

  // the keyboard is on another value of the sheet: show it here too, without selecting it (i null: back to the selection)
  peek(store, i) {
    const l = this.layer;
    if (!l || l.crop) return;
    if (this.peekEl) { this.peekEl.remove(); this.peekEl = null; }
    const sel = this.last && store.values[this.last.i];
    const v = i === null || i === undefined ? sel : store.values[i];
    if (!v || v.p !== l.blk.p || v.b !== l.blk.id) return;
    l.pan.classList.add('slide');
    const away = !(i === null || i === undefined || i === (this.last && this.last.i));
    const ext = this.extent(store, l.blk, v, l);
    l.ext = ext;
    this.apply(l, this.place(l, ext));
    if (this.tagEl) {
      this.tagEl.classList.toggle('slide', true);
      if (away) this.tagEl.classList.remove('on'); else { this.moveTag(l, v, true); this.tagEl.classList.add('on'); }
    }
    if (!away || !v.x) return;
    const { blk } = l, { bi } = blk, S = l.S;
    const mx = bi.w / (blk.x[2] - blk.x[0]), my = bi.h / (blk.x[3] - blk.x[1]);
    const b = v.ix ? [v.ix[0] - 3, v.ix[1] - 3, v.ix[2] + 3, v.ix[3] + 3]
                   : [(v.x[0] - blk.x[0]) * mx, (v.x[1] - blk.x[1]) * my, (v.x[2] - blk.x[0]) * mx, (v.x[3] - blk.x[1]) * my];
    const g = svg('g', { class: 'lp-peek' });
    for (const [cls, w] of [['dark', 4], ['light', 2]]) {
      const r = svg('rect', { x: b[0], y: b[1], width: b[2] - b[0], height: b[3] - b[1], class: cls });
      r.style.strokeWidth = w / S;
      g.append(r);
    }
    l.svg.append(g);
    this.peekEl = g;
  }

  // the window changed size: put the pan back where it belongs, at once
  relayout() {
    const l = this.layer;
    if (!l || l.crop || !this.last) return;
    l.pan.classList.remove('slide');
    if (this.tagEl) this.tagEl.classList.remove('slide');
    const { store, i } = this.last, v = store.values[i];
    const ext = this.extent(store, l.blk, v, l);
    l.ext = ext;
    this.apply(l, this.place(l, ext));
    this.paint(l, store, l.blk, v, this.last.draws, this.last.extra, false);
    this.moveTag(l, v, false);
  }
}

// The findings: the card, the list with its filters, the run numbers and the crop and evidence dialogs.
import { fmt, KIND, KINDS, STATUS, STATUSES, PART, UNCONFIRMED } from './data.js';

const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; };
const hid = e => { e.setAttribute('aria-hidden', 'true'); return e; };
const cap = s => (s ? s[0].toUpperCase() + s.slice(1) : s);
const val = n => (n === undefined || n === null ? '—' : fmt(n));
const valWords = n => (n === undefined || n === null ? 'none' : fmt(n));
const plural = (n, one, many) => `${fmt(n)} ${n === 1 ? one : many}`;
export const VIRTUAL_ABOVE = 200;   // rows; more than this and only the rows near the viewport are in the page

// the other finding of the group that holds the value this one's scan has (a swap): where the file put it
export function siblingOf(store, f) {
  const g = store.groupById.get(f.group);
  if (!g || f.scan === undefined || f.file === undefined) return null;
  const sibs = g.findings.map(id => store.itemById.get(id)).filter(o => o && o.id !== f.id && (o.precinct !== f.precinct || o.part !== f.part));
  return sibs.find(o => o.file === f.scan && o.scan === f.file) || null;
}

// the one plain sentence for what kind of slip this is
export function sentence(store, f) {
  const sib = siblingOf(store, f);
  const v = f.ref === undefined ? null : store.values[f.ref];
  if (f.scan === undefined && (f.kind === 'wrong_column' || f.kind === 'wrong_precinct')) {
    return `The file has ${val(f.file)} under precinct ${f.precinct}${f.part && f.part !== 'votes' ? `, ${PART[f.part]}` : ''}. The scan has no value there.`;
  }
  switch (f.kind) {
    case 'wrong_column':
      return `On the scan this vote is under ${v ? v.r : PART[f.part] || 'one column'}. ` +
        (sib ? `The file has it under ${PART[sib.part] || 'another column'}.` : 'The file has it under another column.');
    case 'wrong_precinct':
      return `On the scan this value is under precinct ${f.precinct}. ` +
        (sib ? `The file has it under precinct ${sib.precinct}.` : 'The file has it under another precinct.');
    case 'missing_row': return 'The scan has this value. The file has no row for it.';
    case 'extra_row': return 'The file has a row here that is not on the scan.';
    case 'file_row_fails_own_total': return "The parts of this row in the file do not add to the row's own total in the file.";
    default: return 'The file and the scan give different numbers for this one value.';
  }
}

// the line above the loupe: page, contest, row label, precinct
export const contextLine = (store, f) => [f.page ? `Page ${f.page}` : null, f.office, f.row, f.precinct ? `precinct ${f.precinct}` : null].filter(Boolean).join(' · ');

export function renderFindingCard(root, store, f, { onCrop, onEvidence }) {
  root.replaceChildren();
  root.className = 'card finding';
  root.setAttribute('aria-label', 'Selected finding');
  const kind = KIND[f.kind] || { word: f.kind, glyph: '' };
  const st = STATUS[f.status] || { word: f.status, glyph: '', line: '' };
  root.append(el('p', 'eyebrow', [f.office, f.page ? `page ${f.page}` : null].filter(Boolean).join(' · ')));
  root.append(el('h2', '', [f.row, f.precinct ? `precinct ${f.precinct}` : null, PART[f.part]].filter(Boolean).join(' · ')));
  const pair = el('div', 'two-values');
  for (const [label, n, cls] of [['Public file', f.file, 'file'], ['Scan', f.scan, 'scan']]) {
    const d = el('div', 'one ' + cls);
    d.append(el('span', 'lab', label), el('span', 'fig', val(n)));
    if (n === undefined || n === null) d.firstChild.after(Object.assign(el('span', 'sr', ': none')));
    pair.append(d);
  }
  root.append(pair);
  const k = el('p', 'kind');
  k.append(el('span', 'lab', 'Kind of slip'), el('span', 'kg', kind.glyph), el('span', 'kw', kind.word));
  k.querySelector('.kg').setAttribute('aria-hidden', 'true');
  root.append(k, el('p', 'sentence', sentence(store, f)));
  const dec = el('div', 'decided');
  dec.append(el('span', 'lab', 'Decided by'));
  if (f.sums.length) {
    const ul = el('ul');
    for (const s of f.sums) ul.append(el('li', '', cap(s.name)));
    dec.append(ul);
  } else dec.append(el('span', '', 'No printed sum was recorded for this value.'));
  root.append(dec);
  const status = el('p', 'status ' + (f.status === 'settled_against_file' ? 'ok' : 'open'));
  status.append(hid(el('span', 'sg', st.glyph)), st.line);
  root.append(status);
  root.append(el('p', 'person', UNCONFIRMED));
  if (f.reread_disagrees) {
    root.append(el('p', 'how', `A closer look at this one value read ${val(f.reread_value)}. The printed sums decide.`));
  }
  const btns = el('div', 'btns');
  const crop = el('button', '', 'Open crop'), ev = el('button', '', 'Evidence file');
  crop.type = ev.type = 'button';
  crop.addEventListener('click', () => onCrop(f, crop));
  ev.addEventListener('click', () => onEvidence(f, ev));
  btns.append(crop, ev);
  root.append(btns);
}

// ---- the dialog: the group's crop with the sums in words, or the finding's evidence
export class Dialog {
  constructor(root) {
    this.root = root; this.title = root.querySelector('.dlg-title'); this.body = root.querySelector('.dlg-body');
    this.opener = null; this.evidence = null;
    root.querySelector('.dlg-close').addEventListener('click', () => root.close());
    root.addEventListener('close', () => { if (this.opener && this.opener.isConnected) this.opener.focus(); this.opener = null; });
    root.addEventListener('click', e => { if (e.target === root) root.close(); });   // a click on the backdrop
  }
  open(title, nodes, opener) {
    this.opener = opener || document.activeElement;
    this.title.textContent = title;
    this.body.replaceChildren(...nodes);
    if (!this.root.open) this.root.showModal();
    this.root.querySelector('.dlg-close').focus();
  }
  crop(store, f, opener) {
    const g = store.groupById.get(f.group);
    const nodes = [];
    if (g && g.crop) {
      const fig = el('figure', 'dlg-fig');
      const img = el('img');
      img.src = g.crop;
      img.alt = `The scan around ${f.row || 'the row'}, precinct ${f.precinct}, as cropped by the audit`;
      fig.append(img);
      nodes.push(fig);
    } else nodes.push(el('p', 'dlg-note', 'No crop was saved for this group.'));
    nodes.push(el('p', 'dlg-note', 'The scan is the source. Add the figures up yourself.'));
    for (const s of f.sums) {
      const d = el('div', 'dlg-sum');
      d.append(el('h3', '', cap(s.name)));
      const ul = el('ul');
      ul.append(el('li', '', `With the public file's value it adds to ${val(s.with_file)}, and ${s.holds_file ? 'matches' : 'does not match'}.`));
      ul.append(el('li', '', `With the scan's value it adds to ${val(s.with_scan)}, and ${s.holds_scan ? 'matches' : 'does not match'}.`));
      ul.append(el('li', '', `The printed total (${s.label || 'printed'}) is ${val(s.printed)}.`));
      d.append(ul);
      nodes.push(d);
    }
    this.open(`Crop · ${[f.row, f.precinct ? `precinct ${f.precinct}` : null, PART[f.part]].filter(Boolean).join(' · ')}`, nodes, opener);
  }
  async evidenceFile(store, f, opener) {
    const fd = store.fd;
    const p = el('p', 'dlg-note', `Finding ${f.id} in ${fd.path || 'the run\'s findings.json'}`);
    const pre = el('pre', 'dlg-pre');
    pre.tabIndex = 0;
    pre.setAttribute('aria-label', `The evidence for finding ${f.id}, as recorded`);
    pre.textContent = 'Loading…';
    this.open('Evidence file', [p, pre], opener);
    try {
      if (!this.evidence || this.evidence.file !== fd.evidence) {
        const r = await fetch(fd.evidence);
        if (!r.ok) throw new Error(String(r.status));
        this.evidence = { file: fd.evidence, doc: await r.json() };
      }
      const rec = this.evidence.doc.findings.find(x => x.id === f.id);
      pre.textContent = rec ? JSON.stringify(rec, null, 2) : `No record of ${f.id} in ${fd.path}.`;
    } catch (e) {
      pre.textContent = `Couldn't load ${fd.evidence}. Open ${fd.path} in the repository instead.`;
    }
  }
}

// ---- the list
const rowOf = f => (f.precinct ? `precinct ${f.precinct}` : '');

export class FindingList {
  constructor(root, store, { onPick, none = false, countEl, filterEl, statusEl }) {
    this.root = root; this.store = store; this.onPick = onPick; this.countEl = countEl; this.filterEl = filterEl; this.statusEl = statusEl;
    this.all = none ? [] : store.items;
    this.fs = new Set(); this.fk = new Set();   // filters: statuses, kinds
    this.cur = null; this.sel = null; this.rows = []; this.vis = [];
    root.onkeydown = e => this.keys(e);
    root.onfocus = () => this.mark(true);
    root.onclick = e => { const li = e.target.closest('li[data-id]'); if (li) { this.cur = li.dataset.id; this.mark(); this.pick(); } };
    this.scroller = null;
    this.onScroll = () => { if (this.virtual) this.paint(); };
    addEventListener('scroll', this.onScroll, true);
    addEventListener('resize', this.onScroll);
    this.counts(); this.chips(); this.build();
  }
  destroy() { removeEventListener('scroll', this.onScroll, true); removeEventListener('resize', this.onScroll); }

  counts() {
    const fd = this.store.fd, all = this.all, n = all.length;
    if (!fd) { this.countEl.textContent = ''; return; }
    const by = s => all.filter(f => f.status === s).length;
    const parts = [plural(n, 'disagreement', 'disagreements'), `${fmt(by('settled_against_file'))} ${STATUS.settled_against_file.count}`,
                   `${fmt(by('cannot_verify'))} ${STATUS.cannot_verify.count}`];
    if (by('document_inconsistent')) parts.push(`${fmt(by('document_inconsistent'))} ${STATUS.document_inconsistent.count}`);
    parts.push(`${fmt(all.filter(f => f.confirmed_by_person).length)} confirmed by a person`);
    this.countEl.textContent = parts.join(' · ');
  }

  chips() {
    const box = this.filterEl;
    box.replaceChildren();
    const mk = (set, key, label, group) => {
      const b = el('button', 'chip', label);
      b.type = 'button'; b.setAttribute('aria-pressed', 'false'); b.dataset.key = key;
      b.addEventListener('click', () => {
        if (set.has(key)) set.delete(key); else set.add(key);
        b.setAttribute('aria-pressed', String(set.has(key)));
        this.build();
      });
      group.append(b);
    };
    const present = (list, f) => list.filter(x => this.all.some(i => f(i) === x));
    const sg = el('div', 'chips'), kg = el('div', 'chips');
    sg.setAttribute('role', 'group'); sg.setAttribute('aria-label', 'Filter by status');
    kg.setAttribute('role', 'group'); kg.setAttribute('aria-label', 'Filter by kind of slip');
    for (const s of present(STATUSES, i => i.status)) mk(this.fs, s, STATUS[s].word, sg);
    for (const k of present(KINDS, i => i.kind)) mk(this.fk, k, KIND[k].word, kg);
    box.append(...[sg, kg].filter(g => g.children.length));
  }

  // the rows to show: a group line, then one line per finding of the group that passes the filters
  build() {
    const keep = f => (!this.fs.size || this.fs.has(f.status)) && (!this.fk.size || this.fk.has(f.kind));
    const byGroup = new Map();
    for (const f of this.all) { if (!keep(f)) continue; if (!byGroup.has(f.group)) byGroup.set(f.group, []); byGroup.get(f.group).push(f); }
    this.rows = []; this.vis = [];
    for (const [gid, fs] of byGroup) {
      const g = this.store.groupById.get(gid);
      this.rows.push({ g: g || { id: gid, kind: fs[0].kind, row: fs[0].row, precincts: [fs[0].precinct] }, fs, h: 40 });
      for (const f of fs) { this.rows.push({ f, h: 36 }); this.vis.push(f.id); }
    }
    let y = 0;
    for (const r of this.rows) { r.y = y; y += r.h; }
    this.total = y;
    this.virtual = this.rows.length > VIRTUAL_ABOVE;
    this.root.classList.toggle('virtual', this.virtual);
    this.root.style.height = this.virtual ? `${this.total}px` : '';
    if (!this.vis.includes(this.cur)) this.cur = this.vis.includes(this.sel) ? this.sel : this.vis[0] || null;
    this.paint();
    if (this.statusEl) {
      const filtered = this.fs.size || this.fk.size;
      this.statusEl.textContent = filtered ? `Showing ${fmt(this.vis.length)} of ${fmt(this.all.length)}` : '';
    }
  }

  // which rows are in the page: all of them, or (long lists) those within a screen of the viewport
  paint() {
    let list = this.rows;
    if (this.virtual) {
      const r = this.root.getBoundingClientRect();
      const panel = this.root.closest('.panel');
      const sc = panel && panel.scrollHeight > panel.clientHeight + 1 ? panel.getBoundingClientRect() : { top: 0, bottom: innerHeight };
      const y0 = Math.max(0, sc.top - r.top) - 400, y1 = sc.bottom - r.top + 400;
      const curRow = this.rows.find(x => x.f && x.f.id === this.cur);
      list = this.rows.filter(x => (x.y + x.h >= y0 && x.y <= y1) || x === curRow);
    }
    this.root.replaceChildren(...list.map(r => this.li(r)));
    this.mark();
    this.shown = list.length;
  }

  li(r) {
    const li = el('li');
    if (this.virtual) { li.style.position = 'absolute'; li.style.top = `${r.y}px`; li.style.height = `${r.h}px`; li.style.left = li.style.right = '0'; }
    if (r.g) {
      const g = r.g, k = KIND[g.kind] || { word: g.kind, glyph: '' };
      li.className = 'grp'; li.setAttribute('role', 'presentation');
      const pr = g.precincts && g.precincts.length ? `${g.precincts.length === 1 ? 'precinct' : 'precincts'} ${g.precincts.join(', ')}` : '';
      li.append(hid(el('span', 'kg', k.glyph)), el('span', 'kw', k.word), el('span', 'rl', g.row || ''), el('span', 'pc', pr));
      return li;
    }
    const f = r.f, st = STATUS[f.status] || { word: f.status, glyph: '' };
    li.id = `finding-${f.id}`; li.dataset.id = f.id; li.className = 'fnd';
    li.setAttribute('role', 'option');
    li.setAttribute('aria-selected', String(f.id === this.sel));
    li.setAttribute('aria-label', `${KIND[f.kind] ? KIND[f.kind].word : f.kind}, ${f.row || ''}, ${rowOf(f)}, ${PART[f.part] || ''}. Public file ${valWords(f.file)}, scan ${valWords(f.scan)}. ${st.word}.`);
    li.append(el('span', 'wh', [f.precinct ? `precinct ${f.precinct}` : null, PART[f.part]].filter(Boolean).join(' · ')));
    const v = el('span', 'vs');
    v.append(el('span', 'fv', val(f.file)), el('span', 'ar', '→'), el('span', 'sv', val(f.scan)));
    li.append(v);
    const s = el('span', 'st ' + (f.status === 'settled_against_file' ? 'ok' : 'open'));
    s.append(hid(el('span', 'sg', st.glyph)), st.word);
    li.append(s);
    return li;
  }

  keys(e) {
    const n = this.vis.length;
    if (!n) return;
    let i = Math.max(0, this.vis.indexOf(this.cur));
    if (e.key === 'ArrowDown') i = Math.min(n - 1, i + 1);
    else if (e.key === 'ArrowUp') i = Math.max(0, i - 1);
    else if (e.key === 'Home') i = 0;
    else if (e.key === 'End') i = n - 1;
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.pick(); return; }
    else return;
    e.preventDefault();
    this.cur = this.vis[i];
    this.mark();
  }
  mark(scroll = false) {
    this.root.querySelectorAll('li.cur').forEach(x => x.classList.remove('cur'));
    const li = this.root.querySelector(`li[data-id="${this.cur}"]`);
    if (!li) { this.root.removeAttribute('aria-activedescendant'); return; }
    li.classList.add('cur');
    this.root.setAttribute('aria-activedescendant', li.id);
    if (scroll || document.activeElement === this.root) li.scrollIntoView({ block: 'nearest' });
  }
  pick() { const f = this.store.itemById.get(this.cur); if (f) this.onPick(f); }
  // the finding that is selected (null: none, a value of the sheet that is not a finding)
  select(id) {
    this.sel = id;
    if (id && this.vis.includes(id)) this.cur = id;
    for (const li of this.root.querySelectorAll('li[data-id]')) li.setAttribute('aria-selected', String(li.dataset.id === id));
    this.mark();
  }
}

// ---- the run's numbers, and the sentence about the reader
export function runFigures(fd) {
  const f = fd.figures || {}, info = fd.run_info || {};
  const out = [];
  const add = (label, n, unit) => { if (n !== undefined && n !== null) out.push([label, n, unit]); };
  add('cells audited', f.cells, 'cells');
  add('right on first read', f.right_first, 'cells');
  add('right after re-reads', f.right_after, f.right_after === 1 ? 'cell' : 'cells');
  add('re-read', f.reread, f.reread === 1 ? 'cell' : 'cells');
  add('disagreements', f.disagreements, 'values');
  add('settled', f.settled, 'values');
  if (info.metered_cost_estimate !== undefined) out.push(['model cost', `$${Number(info.metered_cost_estimate).toFixed(2)}`, 'US dollars']);
  if (info.seconds !== undefined) out.push(['minutes', (info.seconds / 60).toFixed(1), 'min']);
  return out.map(([label, n, unit]) => [label, typeof n === 'number' ? fmt(n) : n, unit]);
}

export function readerSentence(fd) {
  const info = fd.run_info || {}, s = info.sample;
  if (!s || !info.reader || s.row_sums === undefined || s.failing === undefined || !s.sampled_with) return '';
  const pages = [...new Set((s.blocks || []).map(b => (/^p(\d+)-/.exec(b) || [])[1]).filter(Boolean))];
  const what = pages.length === 1 && pages[0] === '1' ? 'the first page' : 'a few pages';
  return `A sample of ${what} read with ${s.sampled_with} failed ${fmt(s.failing)} of ${fmt(s.row_sums)} row sums, so this county was read with ${info.reader}.`;
}

export function renderRun(root, fd) {
  root.replaceChildren();
  if (!fd) return;
  const rows = runFigures(fd);
  if (rows.length) {
    const dl = el('dl', 'nums');
    for (const [label, n, unit] of rows) {
      const d = el('div');
      d.append(el('dt', '', label), el('dd', '', n), el('dd', 'unit', unit));
      dl.append(d);
    }
    root.append(el('h2', '', 'Run numbers'), dl);
  }
  const s = readerSentence(fd);
  if (s) root.append(el('p', 'reader', s));
}
// The adding-machine tape: prints a sum line by line, ending on the printed total.
import { fmt } from './data.js';

const MAX_TOTAL_MS = 900, STEP_MS = 60;
const termLabel = (c, t) => (c.k === 'col' ? t.r : c.k === 'grand_row' ? t.c : `Precinct ${t.c}`);
const heading = c => c.k === 'col' ? `Down the column · precinct ${c.y}` : c.k === 'row' ? `Across the row · ${c.y}`
  : c.k === 'grand_row' ? 'Down the row totals' : 'Across the small totals';
const kindLabel = (kind, v) => (kind === 'col' ? v.r : kind === 'row' ? `Precinct ${v.c}` : kind === 'grand_row' ? v.c : `Precinct ${v.c}`);
// a short heading for a deciding sum; its whole name is in the card under "Decided by"
const sumHeading = (s, f, store) => {
  const v = f.ref === undefined ? null : store.values[f.ref];
  return s.kind === 'col' ? `Down the column${v && !store.isTotal(v) ? ` · precinct ${v.c}` : f.precinct ? ` · precinct ${f.precinct}` : ''}`
    : s.kind === 'row' ? `Across the row${v && v.r ? ` · ${v.r}` : ''}`
    : s.kind === 'grand_row' ? 'Down the row totals' : 'Across the small totals';
};
const val = n => (n === undefined || n === null ? '—' : fmt(n));
const cap = s => (s ? s[0].toUpperCase() + s.slice(1) : s);

export function termLines(store, c) {
  const terms = store.termsOf(c);
  const row = t => ({ label: termLabel(c, t), fig: fmt(t.v), i: t.i });
  if (terms.length <= 5) return terms.map(row);
  return [...terms.slice(0, 3).map(row), { label: `… ${terms.length - 4} more`, fig: '', more: true }, row(terms[terms.length - 1])];
}

// a fine zigzag along the lower edge, 6 px deep
function tornEdge() {
  const pts = ['0 0', '100% 0', '100% calc(100% - 6px)'];
  const n = 50;
  for (let i = n - 1; i >= 0; i--) pts.push(`${(i * 100 / n).toFixed(2)}% ${i % 2 ? 'calc(100% - 6px)' : '100%'}`);
  return `polygon(${pts.join(', ')})`;
}

function el(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}
function line(label, fig, cls, pick) {
  const d = el('div', 'ln' + (cls ? ' ' + cls : ''));
  d.append(el('span', '', label), el('span', '', fig));
  if (!pick) return d;
  // a term line is a button: it selects its value
  const b = el('button', 'ln pick' + (cls ? ' ' + cls : ''));
  b.type = 'button';
  b.append(...d.children);
  b.addEventListener('click', pick);
  return b;
}

// the lines of a finding's sum, both ways: [{label, file, scan, diff, ref, more}]. `own` is the value the finding sits on.
// Terms hold the scan's value (the ledger's); the file's column swaps in the file's value at the term that differs.
export function pairLines(store, f, s) {
  const own = f.ref;
  const rows = s.terms.map(([ref, val]) => {
    const v = ref === null || ref === undefined ? null : store.values[ref];
    const diff = own !== undefined && ref === own;
    return { label: v ? kindLabel(s.kind, v) : '…', scan: fmt(val), file: diff ? (f.file === undefined ? '—' : fmt(f.file)) : fmt(val), diff, ref: v ? ref : undefined };
  });
  if (!rows.some(r => r.diff) && f.kind === 'extra_row' && f.file !== undefined) {
    // a row only the file has: no term of the scan's sum is it
    rows.push({ label: 'file only', scan: '—', file: fmt(f.file), diff: true });
  }
  if (rows.length <= 6) return rows;
  const keep = new Set([0, 1, rows.length - 1]);
  rows.forEach((r, i) => { if (r.diff) keep.add(i); });
  const out = []; let gap = 0;
  rows.forEach((r, i) => {
    if (keep.has(i)) { if (gap) { out.push({ label: `… ${gap} more`, scan: '', file: '', more: true }); gap = 0; } out.push(r); } else gap++;
  });
  return out;
}

export class Tape {
  constructor(root, reduced, onPick = () => {}) {
    this.onPick = onPick; this.root = root; this.reduced = reduced; this.timers = [];
    root.style.clipPath = tornEdge();
    this.clear();
  }
  stop() { this.timers.forEach(clearTimeout); this.timers = []; }
  // keeps its height while empty, so the panel under it does not jump
  clear() { this.stop(); this.root.style.minHeight = `${this.root.offsetHeight}px`; this.root.replaceChildren(); }
  // a finding: each deciding sum printed twice side by side (the public file's value, the scan's value), then the other
  // sums through the value, quieter. Steps are rows of the pair, 60 ms each, as for a single sum.
  printFinding(store, f, others, animate = true, totalMs = MAX_TOTAL_MS) {
    this.stop();
    this.root.replaceChildren();
    this.root.style.minHeight = '';
    this.root.classList.add('two');
    const steps = [];
    const mk = (box, node) => { node.style.visibility = 'hidden'; box.append(node); steps.push(node); };
    const pair = (cls, a, b, pick) => {
      const row = el('div', 'pair' + (cls ? ' ' + cls : ''));
      for (const side of [a, b]) {
        const cell = el('div', 'ln' + (side.diff ? ' diff' : '') + (side.cls ? ' ' + side.cls : ''));
        const lab = el('span', '', side.label);
        if (side.diff) lab.append(el('span', 'sr', ' (differs)'));
        cell.append(lab, el('span', '', side.fig));
        if (pick && side.ref !== undefined) {
          const bt = el('button', 'ln pick' + (side.diff ? ' diff' : ''));
          bt.type = 'button'; bt.append(...cell.children);
          bt.addEventListener('click', () => this.onPick(side.ref));
          row.append(bt);
        } else row.append(cell);
      }
      return row;
    };
    if (!f.sums.length) this.root.append(el('p', 'empty', 'No printed sum was recorded through this value.'));
    for (const s of f.sums) {
      const box = el('div', 'sum two');
      box.append(el('h3', '', sumHeading(s, f, store)));
      const heads = el('div', 'pair heads');
      heads.append(el('h4', '', "With the public file's value"), el('h4', '', "With the scan's value"));
      box.append(heads);
      for (const l of pairLines(store, f, s)) {
        const cls = l.more ? 'more' : '';
        mk(box, pair(cls, { label: l.label, fig: l.file, diff: l.diff, ref: l.ref, cls }, { label: l.label, fig: l.scan, diff: l.diff, ref: l.ref, cls }, true));
      }
      mk(box, pair('rule', { label: 'adds to', fig: fmt(s.with_file) }, { label: 'adds to', fig: fmt(s.with_scan) }));
      // when the value the finding sits on is this sum's printed total, the file's column carries the file's value there
      const ownIsPrinted = f.ref !== undefined && store.isTotal(store.values[f.ref]) && !s.terms.some(t => t[0] === f.ref);
      mk(box, pair('', { label: 'printed total', fig: ownIsPrinted ? val(f.file) : fmt(s.printed), diff: ownIsPrinted },
                       { label: 'printed total', fig: fmt(s.printed), diff: ownIsPrinted }));
      const res = el('div', 'pair res2');
      for (const holds of [s.holds_file, s.holds_scan]) res.append(el('div', 'res ' + (holds ? 'holds' : 'fails'), holds ? '✓ matches' : '✗ does not match'));
      mk(box, res);
      this.root.append(box);
    }
    if (others.length) {
      const more = el('div', 'others');
      more.append(el('h3', '', 'Other printed sums through this value'));
      this.root.append(more);
      for (const { check: c } of others) {
        const box = el('div', 'sum quiet');
        box.append(el('h3', '', heading(c)));
        const sub = el('div', 'one');
        for (const l of termLines(store, c)) sub.append(line(l.label, l.fig, l.more ? 'more' : '', null));
        sub.append(line('adds to', fmt(c.co), 'rule'), line('printed total', fmt(c.pr)),
                   el('div', 'res ' + (c.ok ? 'holds' : 'fails'), c.ok ? '✓ matches' : '✗ does not match'));
        box.append(sub);
        mk(more, box);
      }
    }
    if (!animate || this.reduced) { steps.forEach(s => (s.style.visibility = '')); return; }
    const step = Math.min(STEP_MS, totalMs / steps.length);
    steps.forEach((s, i) => this.timers.push(setTimeout(() => { s.style.visibility = ''; }, i * step)));
  }

  // sums: [{check, axis}]; the lines are built first, then shown one by one
  print(store, sums, animate = true, totalMs = MAX_TOTAL_MS) {
    this.stop();
    this.root.replaceChildren();
    this.root.style.minHeight = '';
    this.root.classList.remove('two');
    const steps = [];
    if (!sums.length) { this.root.append(el('p', 'empty', 'No printed sum was recorded through this value.')); return; }
    for (const { check: c } of sums) {
      const box = el('div', 'sum');
      const h = el('h3', '', heading(c));
      box.append(h);
      const mk = (node) => { node.style.visibility = 'hidden'; box.append(node); steps.push(node); };
      for (const l of termLines(store, c)) mk(line(l.label, l.fig, l.more ? 'more' : '', l.i === undefined ? null : () => this.onPick(l.i)));
      mk(line('adds to', fmt(c.co), 'rule'));
      mk(line('printed total', fmt(c.pr)));
      mk(el('div', 'res ' + (c.ok ? 'holds' : 'fails'), c.ok ? '✓ matches' : '✗ does not match'));
      this.root.append(box);
    }
    if (!animate || this.reduced) { steps.forEach(s => (s.style.visibility = '')); return; }
    const step = Math.min(STEP_MS, totalMs / steps.length);
    steps.forEach((s, i) => this.timers.push(setTimeout(() => { s.style.visibility = ''; }, i * step)));
  }
}
// The panel's card and the list of sums that do not hold.
import { fmt } from './data.js';

const STATUS = {
  accepted: 'Both printed sums hold.',
  cannot_verify: 'A printed sum through this value does not hold. Not verified.',
};
const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; };

export function describe(store, v) {
  const b = store.block(v);
  const where = [b && b.contest, b && b.cand].filter(Boolean).join(' · ');
  const what = store.isTotal(v)
    ? (v.r === 'col' ? `Printed total, precinct ${v.c}` : v.r === 'row' ? `Printed row total, ${v.c}` : 'Printed grand total')
    : `${v.r} · precinct ${v.c}`;
  return { where, what };
}

export function renderCard(root, store, v) {
  root.replaceChildren();
  if (!v) return;
  const { where, what } = describe(store, v);
  const b = store.block(v);
  root.append(el('p', 'eyebrow', `${b ? b.contest : ''} · page ${v.p}`));
  root.append(el('h2', '', what));
  if (b && b.cand) root.append(el('p', 'sub', b.cand));
  root.append(el('p', 'big', fmt(v.v)));
  root.append(el('p', 'status', store.isTotal(v) ? 'Printed on the scan.' : STATUS[v.s] || ''));
  if (!store.isTotal(v) && v.m) root.append(el('p', 'how', `Read by ${v.m}. Re-read tries: ${v.n ?? 0}.`));
}

export function stageLabel(store, v, sums, f = null) {
  const { where, what } = describe(store, v);
  if (f) {
    const s = sums.map(({ check: c }) => `${c.k === 'col' ? 'column' : c.k === 'row' ? 'row' : 'small totals'} sum ${fmt(c.co)}, printed ${fmt(c.pr)}, ${c.ok ? 'holds' : 'does not hold'}`);
    return `Page ${v.p} of the scan. Selected finding: ${where}, ${what}. Public file ${f.file === undefined ? 'none' : fmt(f.file)}, scan ${f.scan === undefined ? 'none' : fmt(f.scan)}. ${s.join('. ')}.`;
  }
  const s = sums.map(({ check: c }) => `${c.k === 'col' ? 'column' : c.k === 'row' ? 'row' : 'small totals'} sum ${fmt(c.co)}, printed ${fmt(c.pr)}, ${c.ok ? 'holds' : 'does not hold'}`);
  return `Page ${v.p} of the scan. Selected: ${where}, ${what}, value ${fmt(v.v)}. ${s.join('. ')}.`;
}

export class FailList {
  constructor(root, store, onPick, { none = false } = {}) {
    this.root = root; this.store = store; this.onPick = onPick; this.cur = 0; this.sel = null;
    this.items = none ? [] : store.checks.filter(c => !c.ok);
    root.replaceChildren(...this.items.map((c, n) => this.row(c, n)));
    root.onkeydown = e => this.keys(e);
    root.onfocus = () => this.mark();
  }
  row(c, n) {
    const b = this.store.blocks.get(`${c.p}:${c.b}`);
    const li = el('li');
    li.id = `fail-${n}`; li.setAttribute('role', 'option'); li.setAttribute('aria-selected', 'false');
    const lab = c.k === 'col' ? `Precinct ${c.y}` : c.k === 'row' ? `Row ${c.y}` : 'Small totals to grand total';
    li.append(el('span', 'a', lab), el('span', 'b', `printed ${fmt(c.pr)}`),

        (sib ? `The file has it under ${PART[sib.part] || 'another column'}.` : 'The file has it under another column.');
    case 'wrong_precinct':
      return `On the scan this value is under precinct ${f.precinct}. ` +
        (sib ? `The file has it under precinct ${sib.precinct}.` : 'The file has it under another precinct.');
    case 'missing_row': return 'The scan has this value. The file has no row for it.';
    case 'extra_row': return 'The file has a row here that is not on the scan.';
    case 'file_row_fails_own_total': return "The parts of this row in the file do not add to the row's own total in the file.";
    default: return 'The file and the scan give different numbers for this one value.';
  }
}

// the line above the loupe: page, contest, row label, precinct
export const contextLine = (store, f) => [f.page ? `Page ${f.page}` : null, f.office, f.row, f.precinct ? `precinct ${f.precinct}` : null].filter(Boolean).join(' · ');

export function renderFindingCard(root, store, f, { onCrop, onEvidence }) {
  root.replaceChildren();
  root.className = 'card finding';
  root.setAttribute('aria-label', 'Selected finding');
  const kind = KIND[f.kind] || { word: f.kind, glyph: '' };
  const st = STATUS[f.status] || { word: f.status, glyph: '', line: '' };
  root.append(el('p', 'eyebrow', [f.office, f.page ? `page ${f.page}` : null].filter(Boolean).join(' · ')));
  root.append(el('h2', '', [f.row, f.precinct ? `precinct ${f.precinct}` : null, PART[f.part]].filter(Boolean).join(' · ')));
  const pair = el('div', 'two-values');
  for (const [label, n, cls] of [['Public file', f.file, 'file'], ['Scan', f.scan, 'scan']]) {
    const d = el('div', 'one ' + cls);
    d.append(el('span', 'lab', label), el('span', 'fig', val(n)));
    if (n === undefined || n === null) d.firstChild.after(Object.assign(el('span', 'sr', ': none')));
    pair.append(d);
  }
  root.append(pair);
  const k = el('p', 'kind');
  k.append(el('span', 'lab', 'Kind of slip'), el('span', 'kg', kind.glyph), el('span', 'kw', kind.word));
  k.querySelector('.kg').setAttribute('aria-hidden', 'true');
  root.append(k, el('p', 'sentence', sentence(store, f)));
  const dec = el('div', 'decided');
  dec.append(el('span', 'lab', 'Decided by'));
  if (f.sums.length) {
    const ul = el('ul');
    for (const s of f.sums) ul.append(el('li', '', cap(s.name)));
    dec.append(ul);
  } else dec.append(el('span', '', 'No printed sum was recorded for this value.'));
  root.append(dec);
  const status = el('p', 'status ' + (f.status === 'settled_against_file' ? 'ok' : 'open'));
  status.append(hid(el('span', 'sg', st.glyph)), st.line);
  root.append(status);
  root.append(el('p', 'person', UNCONFIRMED));
  if (f.reread_disagrees) {
    root.append(el('p', 'how', `A closer look at this one value read ${val(f.reread_value)}. The printed sums decide.`));
  }
  const btns = el('div', 'btns');
  const crop = el('button', '', 'Open crop'), ev = el('button', '', 'Evidence file');
  crop.type = ev.type = 'button';
  crop.addEventListener('click', () => onCrop(f, crop));
  ev.addEventListener('click', () => onEvidence(f, ev));
  btns.append(crop, ev);
  root.append(btns);
}

// ---- the dialog: the group's crop with the sums in words, or the finding's evidence
export class Dialog {
  constructor(root) {
    this.root = root; this.title = root.querySelector('.dlg-title'); this.body = root.querySelector('.dlg-body');
    this.opener = null; this.evidence = null;
    root.querySelector('.dlg-close').addEventListener('click', () => root.close());
    root.addEventListener('close', () => { if (this.opener && this.opener.isConnected) this.opener.focus(); this.opener = null; });
    root.addEventListener('click', e => { if (e.target === root) root.close(); });   // a click on the backdrop
  }
  open(title, nodes, opener) {
    this.opener = opener || document.activeElement;
    this.title.textContent = title;
    this.body.replaceChildren(...nodes);
    if (!this.root.open) this.root.showModal();
    this.root.querySelector('.dlg-close').focus();
  }
  crop(store, f, opener) {
    const g = store.groupById.get(f.group);
    const nodes = [];
    if (g && g.crop) {
      const fig = el('figure', 'dlg-fig');
      const img = el('img');
      img.src = g.crop;
      img.alt = `The scan around ${f.row || 'the row'}, precinct ${f.precinct}, as cropped by the audit`;
      fig.append(img);
      nodes.push(fig);
    } else nodes.push(el('p', 'dlg-note', 'No crop was saved for this group.'));
    nodes.push(el('p', 'dlg-note', 'The scan is the source. Add the figures up yourself.'));
    for (const s of f.sums) {
      const d = el('div', 'dlg-sum');
      d.append(el('h3', '', cap(s.name)));
      const ul = el('ul');
      ul.append(el('li', '', `With the public file's value it adds to ${val(s.with_file)}, and ${s.holds_file ? 'matches' : 'does not match'}.`));
      ul.append(el('li', '', `With the scan's value it adds to ${val(s.with_scan)}, and ${s.holds_scan ? 'matches' : 'does not match'}.`));
      ul.append(el('li', '', `The printed total (${s.label || 'printed'}) is ${val(s.printed)}.`));
      d.append(ul);
      nodes.push(d);
    }
    this.open(`Crop · ${[f.row, f.precinct ? `precinct ${f.precinct}` : null, PART[f.part]].filter(Boolean).join(' · ')}`, nodes, opener);
  }
  async evidenceFile(store, f, opener) {
    const fd = store.fd;
    const p = el('p', 'dlg-note', `Finding ${f.id} in ${fd.path || 'the run\'s findings.json'}`);
    const pre = el('pre', 'dlg-pre');
    pre.tabIndex = 0;
    pre.setAttribute('aria-label', `The evidence for finding ${f.id}, as recorded`);
    pre.textContent = 'Loading…';
    this.open('Evidence file', [p, pre], opener);
    try {
      if (!this.evidence || this.evidence.file !== fd.evidence) {
        const r = await fetch(fd.evidence);
        if (!r.ok) throw new Error(String(r.status));
        this.evidence = { file: fd.evidence, doc: await r.json() };
      }
      const rec = this.evidence.doc.findings.find(x => x.id === f.id);
      pre.textContent = rec ? JSON.stringify(rec, null, 2) : `No record of ${f.id} in ${fd.path}.`;
    } catch (e) {
      pre.textContent = `Couldn't load ${fd.evidence}. Open ${fd.path} in the repository instead.`;
    }
  }
}

// ---- the list
const rowOf = f => (f.precinct ? `precinct ${f.precinct}` : '');

export class FindingList {
  constructor(root, store, { onPick, none = false, countEl, filterEl, statusEl }) {
    this.root = root; this.store = store; this.onPick = onPick; this.countEl = countEl; this.filterEl = filterEl; this.statusEl = statusEl;
    this.all = none ? [] : store.items;
    this.fs = new Set(); this.fk = new Set();   // filters: statuses, kinds
    this.cur = null; this.sel = null; this.rows = []; this.vis = [];
    root.onkeydown = e => this.keys(e);
    root.onfocus = () => this.mark(true);
    root.onclick = e => { const li = e.target.closest('li[data-id]'); if (li) { this.cur = li.dataset.id; this.mark(); this.pick(); } };
    this.scroller = null;
    this.onScroll = () => { if (this.virtual) this.paint(); };
    addEventListener('scroll', this.onScroll, true);
    addEventListener('resize', this.onScroll);
    this.counts(); this.chips(); this.build();
  }
  destroy() { removeEventListener('scroll', this.onScroll, true); removeEventListener('resize', this.onScroll); }

  counts() {
    const fd = this.store.fd, all = this.all, n = all.length;
    if (!fd) { this.countEl.textContent = ''; return; }
    const by = s => all.filter(f => f.status === s).length;
    const parts = [plural(n, 'disagreement', 'disagreements'), `${fmt(by('settled_against_file'))} ${STATUS.settled_against_file.count}`,
                   `${fmt(by('cannot_verify'))} ${STATUS.cannot_verify.count}`];
    if (by('document_inconsistent')) parts.push(`${fmt(by('document_inconsistent'))} ${STATUS.document_inconsistent.count}`);
    parts.push(`${fmt(all.filter(f => f.confirmed_by_person).length)} confirmed by a person`);
    this.countEl.textContent = parts.join(' · ');
  }

  chips() {
    const box = this.filterEl;
    box.replaceChildren();
    const mk = (set, key, label, group) => {
      const b = el('button', 'chip', label);
      b.type = 'button'; b.setAttribute('aria-pressed', 'false'); b.dataset.key = key;
      b.addEventListener('click', () => {
        if (set.has(key)) set.delete(key); else set.add(key);
        b.setAttribute('aria-pressed', String(set.has(key)));
        this.build();
      });
      group.append(b);
    };
    const present = (list, f) => list.filter(x => this.all.some(i => f(i) === x));
    const sg = el('div', 'chips'), kg = el('div', 'chips');
    sg.setAttribute('role', 'group'); sg.setAttribute('aria-label', 'Filter by status');
    kg.setAttribute('role', 'group'); kg.setAttribute('aria-label', 'Filter by kind of slip');
    for (const s of present(STATUSES, i => i.status)) mk(this.fs, s, STATUS[s].word, sg);
    for (const k of present(KINDS, i => i.kind)) mk(this.fk, k, KIND[k].word, kg);
    box.append(...[sg, kg].filter(g => g.children.length));

    box.append(...[sg, kg].filter(g => g.children.length));
  }

  // the rows to show: a group line, then one line per finding of the group that passes the filters
  build() {
    const keep = f => (!this.fs.size || this.fs.has(f.status)) && (!this.fk.size || this.fk.has(f.kind));
    const byGroup = new Map();
    for (const f of this.all) { if (!keep(f)) continue; if (!byGroup.has(f.group)) byGroup.set(f.group, []); byGroup.get(f.group).push(f); }
    this.rows = []; this.vis = [];
    for (const [gid, fs] of byGroup) {
      const g = this.store.groupById.get(gid);
      this.rows.push({ g: g || { id: gid, kind: fs[0].kind, row: fs[0].row, precincts: [fs[0].precinct] }, fs, h: 40 });
      for (const f of fs) { this.rows.push({ f, h: 36 }); this.vis.push(f.id); }
    }
    let y = 0;
    for (const r of this.rows) { r.y = y; y += r.h; }
    this.total = y;
    this.virtual = this.rows.length > VIRTUAL_ABOVE;
    this.root.classList.toggle('virtual', this.virtual);
    this.root.style.height = this.virtual ? `${this.total}px` : '';
    if (!this.vis.includes(this.cur)) this.cur = this.vis.includes(this.sel) ? this.sel : this.vis[0] || null;
    this.paint();
    if (this.statusEl) {
      const filtered = this.fs.size || this.fk.size;
      this.statusEl.textContent = filtered ? `Showing ${fmt(this.vis.length)} of ${fmt(this.all.length)}` : '';
    }
  }

  // which rows are in the page: all of them, or (long lists) those within a screen of the viewport
  paint() {
    let list = this.rows;
    if (this.virtual) {
      const r = this.root.getBoundingClientRect();
      const panel = this.root.closest('.panel');
      const sc = panel && panel.scrollHeight > panel.clientHeight + 1 ? panel.getBoundingClientRect() : { top: 0, bottom: innerHeight };
      const y0 = Math.max(0, sc.top - r.top) - 400, y1 = sc.bottom - r.top + 400;
      const curRow = this.rows.find(x => x.f && x.f.id === this.cur);
      list = this.rows.filter(x => (x.y + x.h >= y0 && x.y <= y1) || x === curRow);
    }
    this.root.replaceChildren(...list.map(r => this.li(r)));
    this.mark();
    this.shown = list.length;
  }

  li(r) {
    const li = el('li');
    if (this.virtual) { li.style.position = 'absolute'; li.style.top = `${r.y}px`; li.style.height = `${r.h}px`; li.style.left = li.style.right = '0'; }
    if (r.g) {
      const g = r.g, k = KIND[g.kind] || { word: g.kind, glyph: '' };
      li.className = 'grp'; li.setAttribute('role', 'presentation');
      const pr = g.precincts && g.precincts.length ? `${g.precincts.length === 1 ? 'precinct' : 'precincts'} ${g.precincts.join(', ')}` : '';
      li.append(hid(el('span', 'kg', k.glyph)), el('span', 'kw', k.word), el('span', 'rl', g.row || ''), el('span', 'pc', pr));
      return li;
    }
    const f = r.f, st = STATUS[f.status] || { word: f.status, glyph: '' };
    li.id = `finding-${f.id}`; li.dataset.id = f.id; li.className = 'fnd';
    li.setAttribute('role', 'option');
    li.setAttribute('aria-selected', String(f.id === this.sel));
    li.setAttribute('aria-label', `${KIND[f.kind] ? KIND[f.kind].word : f.kind}, ${f.row || ''}, ${rowOf(f)}, ${PART[f.part] || ''}. Public file ${valWords(f.file)}, scan ${valWords(f.scan)}. ${st.word}.`);
    li.append(el('span', 'wh', [f.precinct ? `precinct ${f.precinct}` : null, PART[f.part]].filter(Boolean).join(' · ')));
    const v = el('span', 'vs');
    v.append(el('span', 'fv', val(f.file)), el('span', 'ar', '→'), el('span', 'sv', val(f.scan)));
    li.append(v);
    const s = el('span', 'st ' + (f.status === 'settled_against_file' ? 'ok' : 'open'));
    s.append(hid(el('span', 'sg', st.glyph)), st.word);
    li.append(s);
    return li;
  }

  keys(e) {
    const n = this.vis.length;
    if (!n) return;
    let i = Math.max(0, this.vis.indexOf(this.cur));
    if (e.key === 'ArrowDown') i = Math.min(n - 1, i + 1);
    else if (e.key === 'ArrowUp') i = Math.max(0, i - 1);
    else if (e.key === 'Home') i = 0;
    else if (e.key === 'End') i = n - 1;
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.pick(); return; }
    else return;
    e.preventDefault();
    this.cur = this.vis[i];
    this.mark();
  }
  mark(scroll = false) {
    this.root.querySelectorAll('li.cur').forEach(x => x.classList.remove('cur'));
    const li = this.root.querySelector(`li[data-id="${this.cur}"]`);
    if (!li) { this.root.removeAttribute('aria-activedescendant'); return; }
    li.classList.add('cur');
    this.root.setAttribute('aria-activedescendant', li.id);
    if (scroll || document.activeElement === this.root) li.scrollIntoView({ block: 'nearest' });
  }
  pick() { const f = this.store.itemById.get(this.cur); if (f) this.onPick(f); }
  // the finding that is selected (null: none, a value of the sheet that is not a finding)
  select(id) {
    this.sel = id;
    if (id && this.vis.includes(id)) this.cur = id;
    for (const li of this.root.querySelectorAll('li[data-id]')) li.setAttribute('aria-selected', String(li.dataset.id === id));
    this.mark();
  }
}

// ---- the run's numbers, and the sentence about the reader
export function runFigures(fd) {
  const f = fd.figures || {}, info = fd.run_info || {};
  const out = [];
  const add = (label, n, unit) => { if (n !== undefined && n !== null) out.push([label, n, unit]); };
  add('cells audited', f.cells, 'cells');
  add('right on first read', f.right_first, 'cells');
  add('right after re-reads', f.right_after, f.right_after === 1 ? 'cell' : 'cells');
  add('re-read', f.reread, f.reread === 1 ? 'cell' : 'cells');
  add('disagreements', f.disagreements, 'values');
  add('settled', f.settled, 'values');
  if (info.metered_cost_estimate !== undefined) out.push(['model cost', `$${Number(info.metered_cost_estimate).toFixed(2)}`, 'US dollars']);
  if (info.seconds !== undefined) out.push(['minutes', (info.seconds / 60).toFixed(1), 'min']);
  return out.map(([label, n, unit]) => [label, typeof n === 'number' ? fmt(n) : n, unit]);
}

export function readerSentence(fd) {
  const info = fd.run_info || {}, s = info.sample;
  if (!s || !info.reader || s.row_sums === undefined || s.failing === undefined || !s.sampled_with) return '';
  const pages = [...new Set((s.blocks || []).map(b => (/^p(\d+)-/.exec(b) || [])[1]).filter(Boolean))];
  const what = pages.length === 1 && pages[0] === '1' ? 'the first page' : 'a few pages';
  return `A sample of ${what} read with ${s.sampled_with} failed ${fmt(s.failing)} of ${fmt(s.row_sums)} row sums, so this county was read with ${info.reader}.`;
}

export function renderRun(root, fd) {
  root.replaceChildren();
  if (!fd) return;
  const rows = runFigures(fd);
  if (rows.length) {
    const dl = el('dl', 'nums');
    for (const [label, n, unit] of rows) {
      const d = el('div');
      d.append(el('dt', '', label), el('dd', '', n), el('dd', 'unit', unit));
      dl.append(d);
    }
    root.append(el('h2', '', 'Run numbers'), dl);
  }
  const s = readerSentence(fd);
  if (s) root.append(el('p', 'reader', s));
}
// The adding-machine tape: prints a sum line by line, ending on the printed total.
import { fmt } from './data.js';

const MAX_TOTAL_MS = 900, STEP_MS = 60;
const termLabel = (c, t) => (c.k === 'col' ? t.r : c.k === 'grand_row' ? t.c : `Precinct ${t.c}`);
const heading = c => c.k === 'col' ? `Down the column · precinct ${c.y}` : c.k === 'row' ? `Across the row · ${c.y}`
  : c.k === 'grand_row' ? 'Down the row totals' : 'Across the small totals';
const kindLabel = (kind, v) => (kind === 'col' ? v.r : kind === 'row' ? `Precinct ${v.c}` : kind === 'grand_row' ? v.c : `Precinct ${v.c}`);
// a short heading for a deciding sum; its whole name is in the card under "Decided by"
const sumHeading = (s, f, store) => {
  const v = f.ref === undefined ? null : store.values[f.ref];
  return s.kind === 'col' ? `Down the column${v && !store.isTotal(v) ? ` · precinct ${v.c}` : f.precinct ? ` · precinct ${f.precinct}` : ''}`
    : s.kind === 'row' ? `Across the row${v && v.r ? ` · ${v.r}` : ''}`
    : s.kind === 'grand_row' ? 'Down the row totals' : 'Across the small totals';
};
const val = n => (n === undefined || n === null ? '—' : fmt(n));
const cap = s => (s ? s[0].toUpperCase() + s.slice(1) : s);

export function termLines(store, c) {
  const terms = store.termsOf(c);
  const row = t => ({ label: termLabel(c, t), fig: fmt(t.v), i: t.i });
  if (terms.length <= 5) return terms.map(row);
  return [...terms.slice(0, 3).map(row), { label: `… ${terms.length - 4} more`, fig: '', more: true }, row(terms[terms.length - 1])];
}

// a fine zigzag along the lower edge, 6 px deep
function tornEdge() {
  const pts = ['0 0', '100% 0', '100% calc(100% - 6px)'];
  const n = 50;
  for (let i = n - 1; i >= 0; i--) pts.push(`${(i * 100 / n).toFixed(2)}% ${i % 2 ? 'calc(100% - 6px)' : '100%'}`);
  return `polygon(${pts.join(', ')})`;
}

function el(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}
function line(label, fig, cls, pick) {
  const d = el('div', 'ln' + (cls ? ' ' + cls : ''));
  d.append(el('span', '', label), el('span', '', fig));
  if (!pick) return d;
  // a term line is a button: it selects its value
  const b = el('button', 'ln pick' + (cls ? ' ' + cls : ''));
  b.type = 'button';
  b.append(...d.children);
  b.addEventListener('click', pick);
  return b;
}

// the lines of a finding's sum, both ways: [{label, file, scan, diff, ref, more}]. `own` is the value the finding sits on.
// Terms hold the scan's value (the ledger's); the file's column swaps in the file's value at the term that differs.
export function pairLines(store, f, s) {
  const own = f.ref;
  const rows = s.terms.map(([ref, val]) => {
    const v = ref === null || ref === undefined ? null : store.values[ref];
    const diff = own !== undefined && ref === own;
    return { label: v ? kindLabel(s.kind, v) : '…', scan: fmt(val), file: diff ? (f.file === undefined ? '—' : fmt(f.file)) : fmt(val), diff, ref: v ? ref : undefined };
  });
  if (!rows.some(r => r.diff) && f.kind === 'extra_row' && f.file !== undefined) {
    // a row only the file has: no term of the scan's sum is it
    rows.push({ label: 'file only', scan: '—', file: fmt(f.file), diff: true });
  }
  if (rows.length <= 6) return rows;
  const keep = new Set([0, 1, rows.length - 1]);
  rows.forEach((r, i) => { if (r.diff) keep.add(i); });
  const out = []; let gap = 0;
  rows.forEach((r, i) => {
    if (keep.has(i)) { if (gap) { out.push({ label: `… ${gap} more`, scan: '', file: '', more: true }); gap = 0; } out.push(r); } else gap++;
  });
  return out;
}

export class Tape {
  constructor(root, reduced, onPick = () => {}) {
    this.onPick = onPick; this.root = root; this.reduced = reduced; this.timers = [];
    root.style.clipPath = tornEdge();
    this.clear();
  }
  stop() { this.timers.forEach(clearTimeout); this.timers = []; }
  // keeps its height while empty, so the panel under it does not jump
  clear() { this.stop(); this.root.style.minHeight = `${this.root.offsetHeight}px`; this.root.replaceChildren(); }
  // a finding: each deciding sum printed twice side by side (the public file's value, the scan's value), then the other
  // sums through the value, quieter. Steps are rows of the pair, 60 ms each, as for a single sum.
  printFinding(store, f, others, animate = true, totalMs = MAX_TOTAL_MS) {
    this.stop();
    this.root.replaceChildren();
    this.root.style.minHeight = '';
    this.root.classList.add('two');
    const steps = [];
    const mk = (box, node) => { node.style.visibility = 'hidden'; box.append(node); steps.push(node); };
    const pair = (cls, a, b, pick) => {
      const row = el('div', 'pair' + (cls ? ' ' + cls : ''));
      for (const side of [a, b]) {
        const cell = el('div', 'ln' + (side.diff ? ' diff' : '') + (side.cls ? ' ' + side.cls : ''));
        const lab = el('span', '', side.label);
        if (side.diff) lab.append(el('span', 'sr', ' (differs)'));
        cell.append(lab, el('span', '', side.fig));
        if (pick && side.ref !== undefined) {
          const bt = el('button', 'ln pick' + (side.diff ? ' diff' : ''));
          bt.type = 'button'; bt.append(...cell.children);
          bt.addEventListener('click', () => this.onPick(side.ref));
          row.append(bt);
        } else row.append(cell);
      }
      return row;
    };
    if (!f.sums.length) this.root.append(el('p', 'empty', 'No printed sum was recorded through this value.'));
    for (const s of f.sums) {
      const box = el('div', 'sum two');
      box.append(el('h3', '', sumHeading(s, f, store)));
      const heads = el('div', 'pair heads');
      heads.append(el('h4', '', "With the public file's value"), el('h4', '', "With the scan's value"));
      box.append(heads);
      for (const l of pairLines(store, f, s)) {
        const cls = l.more ? 'more' : '';
        mk(box, pair(cls, { label: l.label, fig: l.file, diff: l.diff, ref: l.ref, cls }, { label: l.label, fig: l.scan, diff: l.diff, ref: l.ref, cls }, true));
      }
      mk(box, pair('rule', { label: 'adds to', fig: fmt(s.with_file) }, { label: 'adds to', fig: fmt(s.with_scan) }));
      // when the value the finding sits on is this sum's printed total, the file's column carries the file's value there
      const ownIsPrinted = f.ref !== undefined && store.isTotal(store.values[f.ref]) && !s.terms.some(t => t[0] === f.ref);
      mk(box, pair('', { label: 'printed total', fig: ownIsPrinted ? val(f.file) : fmt(s.printed), diff: ownIsPrinted },
                       { label: 'printed total', fig: fmt(s.printed), diff: ownIsPrinted }));
      const res = el('div', 'pair res2');
      for (const holds of [s.holds_file, s.holds_scan]) res.append(el('div', 'res ' + (holds ? 'holds' : 'fails'), holds ? '✓ matches' : '✗ does not match'));
      mk(box, res);
      this.root.append(box);
    }
    if (others.length) {
      const more = el('div', 'others');
      more.append(el('h3', '', 'Other printed sums through this value'));
      this.root.append(more);
      for (const { check: c } of others) {
        const box = el('div', 'sum quiet');
        box.append(el('h3', '', heading(c)));
        const sub = el('div', 'one');
        for (const l of termLines(store, c)) sub.append(line(l.label, l.fig, l.more ? 'more' : '', null));
        sub.append(line('adds to', fmt(c.co), 'rule'), line('printed total', fmt(c.pr)),
                   el('div', 'res ' + (c.ok ? 'holds' : 'fails'), c.ok ? '✓ matches' : '✗ does not match'));
        box.append(sub);
        mk(more, box);
      }
    }
    if (!animate || this.reduced) { steps.forEach(s => (s.style.visibility = '')); return; }
    const step = Math.min(STEP_MS, totalMs / steps.length);
    steps.forEach((s, i) => this.timers.push(setTimeout(() => { s.style.visibility = ''; }, i * step)));
  }

  // sums: [{check, axis}]; the lines are built first, then shown one by one
  print(store, sums, animate = true, totalMs = MAX_TOTAL_MS) {
    this.stop();
    this.root.replaceChildren();
    this.root.style.minHeight = '';
    this.root.classList.remove('two');
    const steps = [];
    if (!sums.length) { this.root.append(el('p', 'empty', 'No printed sum was recorded through this value.')); return; }
    for (const { check: c } of sums) {
      const box = el('div', 'sum');
      const h = el('h3', '', heading(c));
      box.append(h);
      const mk = (node) => { node.style.visibility = 'hidden'; box.append(node); steps.push(node); };
      for (const l of termLines(store, c)) mk(line(l.label, l.fig, l.more ? 'more' : '', l.i === undefined ? null : () => this.onPick(l.i)));
      mk(line('adds to', fmt(c.co), 'rule'));
      mk(line('printed total', fmt(c.pr)));
      mk(el('div', 'res ' + (c.ok ? 'holds' : 'fails'), c.ok ? '✓ matches' : '✗ does not match'));
      this.root.append(box);
    }
    if (!animate || this.reduced) { steps.forEach(s => (s.style.visibility = '')); return; }
    const step = Math.min(STEP_MS, totalMs / steps.length);
    steps.forEach((s, i) => this.timers.push(setTimeout(() => { s.style.visibility = ''; }, i * step)));
  }
}
// The panel's card and the list of sums that do not hold.
import { fmt } from './data.js';

const STATUS = {
  accepted: 'Both printed sums hold.',
  cannot_verify: 'A printed sum through this value does not hold. Not verified.',
};
const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; };

export function describe(store, v) {
  const b = store.block(v);
  const where = [b && b.contest, b && b.cand].filter(Boolean).join(' · ');
  const what = store.isTotal(v)
    ? (v.r === 'col' ? `Printed total, precinct ${v.c}` : v.r === 'row' ? `Printed row total, ${v.c}` : 'Printed grand total')
    : `${v.r} · precinct ${v.c}`;
  return { where, what };
}

export function renderCard(root, store, v) {
  root.replaceChildren();
  if (!v) return;
  const { where, what } = describe(store, v);
  const b = store.block(v);
  root.append(el('p', 'eyebrow', `${b ? b.contest : ''} · page ${v.p}`));
  root.append(el('h2', '', what));
  if (b && b.cand) root.append(el('p', 'sub', b.cand));
  root.append(el('p', 'big', fmt(v.v)));
  root.append(el('p', 'status', store.isTotal(v) ? 'Printed on the scan.' : STATUS[v.s] || ''));
  if (!store.isTotal(v) && v.m) root.append(el('p', 'how', `Read by ${v.m}. Re-read tries: ${v.n ?? 0}.`));
}

export function stageLabel(store, v, sums, f = null) {
  const { where, what } = describe(store, v);
  if (f) {
    const s = sums.map(({ check: c }) => `${c.k === 'col' ? 'column' : c.k === 'row' ? 'row' : 'small totals'} sum ${fmt(c.co)}, printed ${fmt(c.pr)}, ${c.ok ? 'holds' : 'does not hold'}`);
    return `Page ${v.p} of the scan. Selected finding: ${where}, ${what}. Public file ${f.file === undefined ? 'none' : fmt(f.file)}, scan ${f.scan === undefined ? 'none' : fmt(f.scan)}. ${s.join('. ')}.`;
  }
  const s = sums.map(({ check: c }) => `${c.k === 'col' ? 'column' : c.k === 'row' ? 'row' : 'small totals'} sum ${fmt(c.co)}, printed ${fmt(c.pr)}, ${c.ok ? 'holds' : 'does not hold'}`);
  return `Page ${v.p} of the scan. Selected: ${where}, ${what}, value ${fmt(v.v)}. ${s.join('. ')}.`;
}

export class FailList {
  constructor(root, store, onPick, { none = false } = {}) {
    this.root = root; this.store = store; this.onPick = onPick; this.cur = 0; this.sel = null;
    this.items = none ? [] : store.checks.filter(c => !c.ok);
    root.replaceChildren(...this.items.map((c, n) => this.row(c, n)));
    root.onkeydown = e => this.keys(e);
    root.onfocus = () => this.mark();
  }
  row(c, n) {
    const b = this.store.blocks.get(`${c.p}:${c.b}`);
    const li = el('li');
    li.id = `fail-${n}`; li.setAttribute('role', 'option'); li.setAttribute('aria-selected', 'false');
    const lab = c.k === 'col' ? `Precinct ${c.y}` : c.k === 'row' ? `Row ${c.y}` : 'Small totals to grand total';
    li.append(el('span', 'a', lab), el('span', 'b', `printed ${fmt(c.pr)}`),
              el('span', 'c', `Page ${c.p} · ${[b && b.contest, b && b.cand].filter(Boolean).join(' · ')} · adds to ${fmt(c.co)}`));
    li.addEventListener('click', () => { this.cur = n; this.mark(); this.pick(); });
    return li;
  }
  keys(e) {
    const n = this.items.length;
    if (!n) return;
    if (e.key === 'ArrowDown') this.cur = Math.min(n - 1, this.cur + 1);
    else if (e.key === 'ArrowUp') this.cur = Math.max(0, this.cur - 1);
    else if (e.key === 'Home') this.cur = 0;
    else if (e.key === 'End') this.cur = n - 1;
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.pick(); return; }
    else return;
    e.preventDefault();
    this.mark();
  }
  mark() {
    const li = this.root.children[this.cur];
    this.root.querySelectorAll('li.cur').forEach(x => x.classList.remove('cur'));
    if (!li) return;
    li.classList.add('cur');
    this.root.setAttribute('aria-activedescendant', li.id);
    li.scrollIntoView({ block: 'nearest' });
  }
  pick() { const c = this.items[this.cur]; if (c) this.onPick(c); }
  // show which sum, if any, the selected value sits on
  follow(sums) {
    const on = new Set(sums.map(s => s.check.i));
    this.items.forEach((c, n) => this.root.children[n].setAttribute('aria-selected', String(on.has(c.i))));
  }
}

:root{
  color-scheme: dark;
  --ff-display:"Public Sans",system-ui,sans-serif; --ff-body:"Public Sans",system-ui,sans-serif; --ff-mono:"Courier Prime",ui-monospace,monospace;
  --canvas:#14211B; --surface-1:#1B2B24; --surface-2:#243830; --surface-sunken:#0F1A15;
  --line:#34493F; --line-input:#6F867A;
  --ink:#EEF2EC; --ink-muted:#A9B8AE;
  --accent:#F4F1E8; --accent-ink:#14211B; --focus:#F4F1E8;
  --sheet:#FBFAF5; --sheet-ink:#17181A;
  --data-fails:#F0624D; --data-holds:#7FAEFF;
  --danger:#F0624D; --success:#7FAEFF; --warning:#E9B84A;
  --r-sm:2px; --r-md:4px; --r-lg:8px;
  --ease-out:cubic-bezier(.23,1,.32,1); --ease-in-out:cubic-bezier(.77,0,.175,1);
  --dur-press:120ms; --dur-hover:150ms; --dur-line:350ms; --dur-turn:600ms;
  --pad:24px; --panel:420px;
}
*{box-sizing:border-box}
[hidden]{display:none!important}
html,body{margin:0;height:100%}
body{background:var(--canvas);color:var(--ink);font:400 15px/1.45 var(--ff-body);display:grid;grid-template-rows:52px minmax(0,1fr) auto;min-height:100vh;height:100vh;overflow:hidden}
:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
button{font:inherit;color:inherit}
a{color:var(--ink);text-underline-offset:2px}

.bar{display:flex;align-items:center;gap:20px;padding:0 var(--pad);border-bottom:1px solid var(--line);background:var(--canvas)}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none}
.word{font:800 20px/1 var(--ff-display);letter-spacing:-.03em}
.descriptor{margin:0;color:var(--ink-muted);font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tabs{margin-left:auto;display:flex;border:1px solid var(--line-input);border-radius:var(--r-md);overflow:hidden}
.tabs button{background:none;border:0;padding:6px 14px;cursor:pointer}
.tabs button[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);font-weight:600}

.main{display:grid;grid-template-columns:minmax(760px,1fr) var(--panel);gap:var(--pad);padding:var(--pad);min-height:0}
.stage{position:relative;min-height:0;background:var(--surface-sunken);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden}
.stage::before{content:"";position:absolute;inset:12px;border:1px solid var(--line);border-radius:8px;pointer-events:none}
.viewport{position:absolute;inset:0;perspective:1800px}
.lean{position:absolute;inset:0;transform-style:preserve-3d;will-change:transform}
.pose{position:absolute;left:0;top:0;width:0;height:0;transform-origin:0 0;transform-style:preserve-3d;will-change:transform}
.paper,.stack,.sheet,.marks{position:absolute;left:calc(var(--w) / -2);top:calc(var(--h) / -2);width:var(--w);height:var(--h)}
.paper{transform-style:preserve-3d}
.paper>.stack,.paper>.sheet{left:0;top:0}   /* inside the paper, which is already centred: otherwise the sheet sits half a sheet off the marks */
.stack i.under{background:#000;border:0;box-shadow:calc(var(--inv,1) * 4px) calc(var(--inv,1) * 8px) calc(var(--inv,1) * 18px) calc(var(--inv,1) * 2px) rgba(0,0,0,.85)}
.stack{transform-style:preserve-3d}
.stack i{position:absolute;inset:0;background:#c9c6b8;border-bottom:1px solid #8d8a7d;border-right:1px solid #8d8a7d}
.sheet{background:var(--sheet);color:var(--sheet-ink)}
.sheet img{display:block;width:100%;height:100%;user-select:none;-webkit-user-drag:none}
.far{position:absolute;left:0;right:0;top:0;height:3.5%;background:#000;opacity:.07;pointer-events:none}
.bands{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.marks{overflow:visible;transform:translateZ(calc(var(--inv,1) * .6px))}
.marks rect{fill:transparent;cursor:pointer;stroke:none}
.marks rect:hover{stroke:var(--sheet-ink);stroke-width:calc(2 * var(--u,1))}
.marks rect:focus{outline:none}
.focus-ring{pointer-events:none}
.focus-ring rect{fill:none}
.focus-ring .dark{stroke:var(--sheet-ink);stroke-width:calc(4 * var(--u,1))}
.focus-ring .light{stroke:var(--focus);stroke-width:calc(2 * var(--u,1))}
.bands line{stroke-width:calc(7 * var(--u,1));opacity:.35;fill:none}
.bands line.holds{stroke:var(--data-holds)} .bands line.fails{stroke:var(--data-fails)}
.bands circle{fill:none;stroke-width:calc(3 * var(--u,1))}
.bands circle.holds{stroke:var(--data-holds)} .bands circle.fails{stroke:var(--data-fails)}

.ctx{position:absolute;z-index:2;top:17px;left:24px;right:24px;margin:0;font:400 12px/16px var(--ff-body);color:var(--ink-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center}
.loupe{position:absolute;z-index:2;top:40px;left:50%;transform:translateX(-50%);width:min(576px,calc(100% - 48px));height:240px;background:var(--sheet);color:var(--sheet-ink);border:1px solid var(--sheet-ink);box-shadow:0 1px 1px rgba(0,0,0,.5),0 10px 18px -6px rgba(0,0,0,.55);overflow:hidden}
.loupe.rise{animation:rise 300ms var(--ease-out) both}
@keyframes rise{from{transform:translate(-50%,12px);opacity:0}to{transform:translateX(-50%);opacity:1}}
.lp-view{position:absolute;inset:0;overflow:hidden}
.lp-layer{position:absolute;inset:0;opacity:0;transition:opacity 150ms linear}
.lp-layer.in{opacity:1}
.lp-layer.instant{transition:none}
.lp-pan{position:absolute;left:0;top:0;transform-origin:0 0}
.lp-pan.slide{transition:transform 350ms var(--ease-in-out)}
.lp-pan img{display:block;user-select:none;-webkit-user-drag:none}
.lp-svg{position:absolute;left:0;top:0;overflow:visible}
.lp-svg line{opacity:.26;fill:none}
.lp-svg line.holds{stroke:var(--data-holds)} .lp-svg line.fails{stroke:var(--data-fails)}
.lp-peek rect{fill:none}
.lp-peek .dark{stroke:var(--sheet-ink)} .lp-peek .light{stroke:var(--focus)}
.lp-hit{fill:transparent;cursor:pointer}
.lp-hit:hover{stroke:var(--sheet-ink);stroke-width:1.5}
.lp-ring{fill:none;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.lp-ring.holds{stroke:var(--data-holds)} .lp-ring.fails{stroke:var(--data-fails)}
.lp-note{position:absolute;left:0;right:0;bottom:0;margin:0;padding:4px 10px;background:var(--sheet);border-top:1px solid #9a9c9e;font-size:12px;line-height:16px;color:#4a4d50}
.leader{position:absolute;inset:0;width:100%;height:100%;z-index:3;pointer-events:none;overflow:visible}
.leader{mix-blend-mode:difference}
.leader line{stroke:var(--ink);stroke-opacity:.6;stroke-width:1.5;stroke-linecap:round}

.notice{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);max-width:420px;background:var(--surface-2);border:1px solid var(--danger);border-radius:var(--r-md);padding:16px 20px;font-size:15px;z-index:4}
.controls{position:absolute;left:24px;bottom:24px;right:24px;z-index:2;display:flex;flex-wrap:wrap;align-items:center;gap:4px 14px}
.controls button:not(.primary){background:none;border:0;padding:4px 0;color:var(--ink);text-decoration:underline;text-underline-offset:3px;cursor:pointer}
.controls button:not(.primary):disabled{color:var(--ink-muted);text-decoration:none;cursor:default}
.primary{background:var(--accent);color:var(--accent-ink);border:0;border-radius:var(--r-md);padding:7px 16px;font-weight:600;cursor:pointer;transition:transform var(--dur-press)}
.primary:disabled{cursor:not-allowed}
.primary:not(:disabled):active{transform:translateY(1px)}
.hint{margin:0;color:var(--ink-muted);font-size:12px}
.pageno{color:var(--ink-muted);font-size:13px}

.panel>*{flex:none}
.panel{display:flex;flex-direction:column;gap:12px;min-height:0;overflow-y:auto;padding:0 2px 2px 0}
.tapewrap{filter:drop-shadow(0 1px 0 rgba(0,0,0,.6))}
.tape{background:var(--sheet);color:var(--sheet-ink);padding:12px 14px 20px;font:400 14px/18px var(--ff-mono);min-height:64px;display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0 18px}
.tape h3{margin:0 0 4px;font:600 13px/16px var(--ff-body);color:#4a4d50}
.tape .sum{min-width:0}
.tape .ln{display:flex;justify-content:space-between;gap:12px;white-space:pre}
.tape .ln span:last-child{text-align:right;font-variant-numeric:tabular-nums}
.tape .ln.pick{cursor:pointer}
.tape .ln.pick:hover{background:#e9e6da}
.tape .ln.rule{border-top:1.5px solid var(--sheet-ink);margin-top:2px;padding-top:2px}
.tape .ln.more{color:#4a4d50}
.tape .res{margin-top:4px;padding:0 8px;font-weight:700;display:inline-block;color:var(--sheet-ink)}
.tape .res.holds{background:var(--data-holds)} .tape .res.fails{background:var(--data-fails)}
.tape .empty{margin:0;color:#4a4d50;font:400 14px var(--ff-body);grid-column:1/-1}
.card{background:var(--surface-1);border:1px solid var(--line);border-radius:var(--r-lg);padding:10px 14px;display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:12px;align-items:center}
.card>*{grid-column:1}
.card .eyebrow{margin:0;color:var(--ink-muted);font-size:13px}
.card h2{margin:0;font:600 16px/1.3 var(--ff-body)}
.card .sub{margin:0;color:var(--ink-muted);font-size:13px;line-height:1.3}
.card .big{grid-column:2;grid-row:1/span 3;margin:0;font:700 34px/1 var(--ff-mono);font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.card .status{margin:2px 0 0;font-size:14px}
.card .how{margin:0;color:var(--ink-muted);font-size:12px}
.fails h2{margin:0 0 4px;font:600 13px var(--ff-body);color:var(--ink-muted);letter-spacing:.03em;text-transform:uppercase}
.fails.none h2{text-transform:none;letter-spacing:0;font-size:15px;color:var(--ink)}
.list{list-style:none;margin:0;padding:0;border-top:1px solid var(--line);border-radius:var(--r-sm)}
.list li{display:grid;grid-template-columns:1fr auto;gap:0 12px;padding:6px 10px 6px 12px;border-bottom:1px solid var(--line);border-left:2px solid transparent;cursor:pointer;font-size:14px;line-height:1.35}
.list li .a{font-weight:600} .list li .b{font:400 13px var(--ff-mono);text-align:right;font-variant-numeric:tabular-nums}
.list li .c{grid-column:1/-1;color:var(--ink-muted);font-size:13px}
.list li[aria-selected="true"]{border-left-color:var(--ink);background:var(--surface-1)}
.list li.cur{outline:2px solid var(--focus);outline-offset:-2px}
.list:not(:focus-visible) li.cur{outline:0}
.foot{padding:10px var(--pad) 14px;color:var(--ink-muted);font-size:13px;border-top:1px solid var(--line)}
.foot a{color:var(--ink)}

/* ---- the dock: the primary action and the reason it is blocked (a fixed bar under 900 px) */
.dock{display:contents}
.hint{order:10}
.controls button{min-height:28px}

/* ---- tape lines and the list: buttons and rows that take focus */
.tape button.ln{min-height:24px;align-items:center;width:100%;background:none;border:0;padding:0;margin:0;text-align:left;color:inherit;font:inherit;cursor:pointer}
.tape button.ln:focus-visible{background:var(--sheet-ink);color:var(--sheet);outline:2px solid var(--focus);outline-offset:0}
.list:focus-visible{outline:2px solid var(--focus);outline-offset:2px}

/* ---- states: body[data-state] = loading | error | empty | partial | first-run | ready */
.ghost,.statebox,.flatblock,.skeleton{display:none}
.ghost{position:absolute;inset:0;z-index:1;pointer-events:none;perspective:1800px;overflow:hidden}
.ghost-sheet{position:absolute;left:50%;top:54%;width:min(62%,560px);aspect-ratio:1600/971;background:var(--sheet);opacity:.92;transform:translate(-50%,-50%) rotateX(34deg) rotateZ(-3deg);overflow:hidden}
.scanline{position:absolute;left:0;right:0;top:0;height:3px;background:var(--data-holds);animation:scan 1.6s linear infinite}
@keyframes scan{from{top:-3px}to{top:100%}}
.statebox{position:absolute;left:24px;right:24px;top:24px;z-index:3;margin:0;font:600 15px/1.4 var(--ff-body);text-align:center}
body[data-state="loading"] .ghost{display:block}
body[data-state="loading"] .statebox,body[data-state="first-run"] .statebox{display:block}
body[data-state="loading"] .statebox{top:auto;bottom:80px;font-variant-numeric:tabular-nums}
body[data-state="first-run"] .statebox{top:50%;transform:translateY(-50%);max-width:480px;margin:0 auto}
body[data-state="loading"] .viewport,body[data-state="loading"] .loupe,body[data-state="loading"] .leader,
body[data-state="error"] .viewport,body[data-state="error"] .loupe,body[data-state="error"] .leader,
body[data-state="first-run"] .viewport,body[data-state="first-run"] .loupe,body[data-state="first-run"] .leader,
body[data-state="first-run"] .controls,body[data-state="first-run"] .panel{display:none}
body[data-state="first-run"] .main{grid-template-columns:minmax(0,1fr)}
body[data-state="loading"] .skeleton,body[data-state="error"] .skeleton{display:grid;gap:12px}
body[data-state="loading"] .tapewrap,body[data-state="loading"] .card,body[data-state="loading"] .findings,body[data-state="loading"] .run,body[data-state="loading"] .fails,body[data-state="loading"] .judge,
body[data-state="error"] .tapewrap,body[data-state="error"] .card,body[data-state="error"] .findings,body[data-state="error"] .run,body[data-state="error"] .fails,body[data-state="error"] .judge{display:none}
body[data-state="loading"] .ctx,body[data-state="error"] .ctx,body[data-state="first-run"] .ctx{display:none}
.sk-tape,.sk-card{display:grid;gap:10px;padding:16px 14px;border-radius:var(--r-md)}
.sk-tape{background:var(--surface-2);min-height:150px}
.sk-card{background:var(--surface-1);border:1px solid var(--line);min-height:100px}
.skeleton i{display:block;height:12px;border-radius:var(--r-sm);background:var(--line);animation:pulse 1.6s ease-in-out infinite}
.skeleton i:nth-child(2){width:70%} .skeleton i:nth-child(3){width:85%} .skeleton i:nth-child(4){width:55%}
@keyframes pulse{50%{opacity:.45}}
/* partial: no page image, so the block's own image is shown flat in the sheet zone */
.stage.partial .viewport{display:none}
.stage.partial .flatblock{display:block;position:absolute;z-index:1;left:24px;right:24px;top:calc(40px + 240px + 12px);bottom:84px;overflow:hidden;background:var(--sheet);color:var(--sheet-ink)}
.stage.partial .flatblock p{margin:0;padding:12px;font-size:14px}
.fb-pan{position:absolute;left:0;top:0;transform-origin:0 0}
.fb-pan img{display:block}
.fb-svg{position:absolute;left:0;top:0;overflow:visible}
.fb-svg line{opacity:.26;fill:none} .fb-svg line.holds{stroke:var(--data-holds)} .fb-svg line.fails{stroke:var(--data-fails)}
.fb-hit{fill:transparent;cursor:pointer}
.fb-ring{fill:none;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.fb-ring.holds{stroke:var(--data-holds)} .fb-ring.fails{stroke:var(--data-fails)}

/* ---- the finding: the card, the tape in two columns, the list, the run numbers, the dialog */
.sr{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.lp-tag{position:absolute;left:0;top:0;z-index:2;pointer-events:none;opacity:0;padding:0 6px;background:var(--sheet);color:var(--sheet-ink);border:1px solid var(--sheet-ink);font:400 13px/20px var(--ff-mono);white-space:nowrap;font-variant-numeric:tabular-nums}
.lp-tag.on{opacity:1;transition:opacity 100ms linear}
.lp-tag.slide{transition:transform 350ms var(--ease-in-out),opacity 100ms linear}
.lp-tag::before{content:"";position:absolute;right:5px;top:-6px;width:1px;height:5px;background:var(--sheet-ink)}
.lp-ring2{fill:none;stroke:var(--sheet-ink);stroke-dasharray:5 4;pointer-events:none}
.lp-cropbox{display:flex;align-items:center;justify-content:center;background:var(--sheet)}
.lp-crop{display:block;max-width:100%;max-height:100%;object-fit:contain}
.ticks{pointer-events:none}
.ticks .tick path{fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.ticks .tick.settled path{stroke:var(--data-fails)} .ticks .tick.open path{stroke:var(--warning)}

.card.finding{display:block;padding:12px 14px}
.card.finding .eyebrow{font-size:13px}
.card.finding h2{font-size:16px;margin:0 0 8px}
.two-values{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.two-values .one{border:1px solid var(--line-input);border-radius:var(--r-md);padding:6px 10px 4px;min-width:0;background:var(--surface-sunken)}
.two-values .one.scan{border-color:var(--ink)}
.two-values .lab{display:block;color:var(--ink-muted);font-size:12px;line-height:16px}
.two-values .fig{display:block;font:700 34px/1.1 var(--ff-mono);font-variant-numeric:tabular-nums;letter-spacing:-.02em;overflow-wrap:anywhere}
.card.finding .kind{margin:8px 0 0;font-size:14px;display:flex;gap:6px;align-items:baseline;flex-wrap:wrap}
.card.finding .lab{color:var(--ink-muted);font-size:12px}
.card.finding .kg{font-weight:700;min-width:1ch}
.card.finding .kw{font-weight:600}
.card.finding .sentence{margin:2px 0 6px;font-size:14px;line-height:1.35}
.decided{font-size:13px;line-height:1.35}
.decided ul{margin:2px 0 0;padding-left:16px}
.card.finding .status{margin:8px 0 0;font-size:14px;font-weight:600}
.card.finding .status .sg,.st .sg{display:inline-block;min-width:1.2ch;margin-right:4px}
.card.finding .person{margin:2px 0 0;font-size:13px;color:var(--ink-muted)}
.card.finding .how{margin:4px 0 0;font-size:13px}
.btns{display:flex;gap:8px;margin-top:10px}
.btns button,.dlg-close{min-height:36px;padding:0 14px;background:none;color:var(--ink);border:1px solid var(--line-input);border-radius:var(--r-md);cursor:pointer}
.btns button:hover,.dlg-close:hover{border-color:var(--ink)}

.tape.two{display:block}
.tape .sum.two h3{margin:0 0 2px}
.tape.two .sum+.sum{margin-top:12px;padding-top:8px;border-top:1px dashed #9a9c9e}
.tape .pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 18px}
.tape .pair.heads h4{margin:0 0 2px;font:600 12px/16px var(--ff-body);color:#4a4d50}
.tape .pair.rule{border-top:1.5px solid var(--sheet-ink);margin-top:2px;padding-top:2px}
.tape .pair.rule .ln{border:0;margin:0;padding:0}
.tape .ln.diff{background:#f6e3de;box-shadow:inset 3px 0 0 var(--data-fails);padding-left:5px}
.tape .pair>.ln:last-child.diff{background:#dde8fb;box-shadow:inset 3px 0 0 #2f5fb3}
.tape button.ln.diff:focus-visible{background:var(--sheet-ink)}
.tape .res2{margin-top:4px}
.tape .res2 .res{margin-top:0;display:block;white-space:nowrap;font-size:13px}
.tape .others{margin-top:14px;padding-top:8px;border-top:1px dashed #9a9c9e;color:#4a4d50;font-size:13px}
.tape .others>h3{margin:0 0 4px}
.tape .sum.quiet{margin-top:6px;padding:0;border:0;opacity:.92;font-size:13px}
.tape .sum.quiet .ln{font-size:13px;line-height:16px}
.tape .sum.quiet h3{font-size:12px}

.findings h2,.run h2,.judge h2{margin:0 0 4px;font:600 13px var(--ff-body);color:var(--ink-muted);letter-spacing:.03em;text-transform:uppercase}
.findings.none h2{text-transform:none;letter-spacing:0;font-size:15px;color:var(--ink)}
.findings.none .count,.findings.none .filters,.findings.none .showing{display:none}
.count{margin:0 0 6px;font-size:14px;line-height:1.35;font-variant-numeric:tabular-nums}
.filters{display:grid;gap:6px;margin-bottom:6px}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{min-height:28px;padding:2px 10px;background:none;color:var(--ink);border:1px solid var(--line-input);border-radius:14px;cursor:pointer;font-size:13px}
.chip[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent);font-weight:600}
.showing{margin:0 0 4px;font-size:12px;color:var(--ink-muted);min-height:0}
.showing:empty{display:none}
.flist{list-style:none;margin:0;padding:0;border-top:1px solid var(--line)}
.flist.virtual{position:relative}
.flist li{font-size:14px;line-height:1.3}
.flist li.grp{display:grid;grid-template-columns:auto auto minmax(0,1fr);gap:0 8px;align-items:baseline;padding:8px 10px 2px 12px;background:var(--surface-1);border-bottom:1px solid var(--line)}
.flist li.grp .kg{font-weight:700;min-width:1.2ch;text-align:center}
.flist li.grp .kw{font-weight:600}
.flist li.grp .rl{color:var(--ink);overflow-wrap:anywhere;min-width:0}
.flist li.grp .pc{grid-column:2/-1;color:var(--ink-muted);font-size:13px}
.flist li.fnd{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:0 10px;align-items:center;padding:5px 10px 5px 12px;border-bottom:1px solid var(--line);border-left:2px solid transparent;cursor:pointer;min-height:36px}
.flist li.fnd[aria-selected="true"]{border-left-color:var(--ink);background:var(--surface-2)}
.flist li.fnd.cur{outline:2px solid var(--focus);outline-offset:-2px}
.flist:not(:focus-visible) li.cur{outline:0}
.flist:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.flist .wh{color:var(--ink);font-size:13px}
.flist .vs{font:400 13px var(--ff-mono);font-variant-numeric:tabular-nums;white-space:nowrap}
.flist .ar{margin:0 5px;color:var(--ink-muted)}
.flist .sv{font-weight:700}
.flist .st{font-size:13px;white-space:nowrap;min-width:6.5em}
.flist .st.ok{color:var(--ink)} .flist .st.open{color:var(--warning)}
.flist.virtual li{overflow:hidden}
.flist.virtual li.fnd .wh{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.run{font-size:13px}
.nums{display:grid;grid-template-columns:repeat(auto-fit,minmax(112px,1fr));gap:8px 12px;margin:0}
.nums>div{display:block}
.nums dt{color:var(--ink-muted);font-size:12px;line-height:15px}
.nums dd{margin:0;font:400 15px/18px var(--ff-mono);font-variant-numeric:tabular-nums;display:inline}
.nums dd.unit{font:400 12px var(--ff-body);color:var(--ink-muted);margin-left:4px}
.reader{margin:8px 0 0;color:var(--ink-muted);font-size:13px;line-height:1.4}
.fails summary{cursor:pointer;color:var(--ink-muted);font-size:13px;padding:6px 0;min-height:28px}
.fails summary:hover{color:var(--ink)}
.fails .list{margin-top:4px}
.judge ol{margin:0;padding-left:20px;font-size:14px;color:var(--ink)}
.judge{padding-bottom:4px}

.dlg{background:var(--surface-1);color:var(--ink);border:1px solid var(--line-input);border-radius:var(--r-lg);padding:0;width:min(760px,calc(100vw - 32px));max-height:calc(100vh - 48px)}
.dlg::backdrop{background:rgba(0,0,0,.62)}
.dlg[open]{display:flex;flex-direction:column}
.dlg-head{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--line)}
.dlg-title{margin:0;font:600 16px/1.3 var(--ff-body);overflow-wrap:anywhere}
.dlg-body{padding:12px 16px 16px;overflow:auto;min-height:0}
.dlg-fig{margin:0 0 10px;background:var(--sheet);padding:6px}
.dlg-fig img{display:block;max-width:100%;height:auto}
.dlg-note{margin:0 0 10px;font-size:14px;color:var(--ink-muted)}
.dlg-sum{margin:0 0 10px}
.dlg-sum h3{margin:0 0 2px;font:600 14px/1.3 var(--ff-body)}
.dlg-sum ul{margin:0;padding-left:18px;font-size:14px;line-height:1.4}
.dlg-pre{margin:0;padding:10px;background:var(--surface-sunken);border:1px solid var(--line);border-radius:var(--r-md);font:400 12px/1.45 var(--ff-mono);overflow:auto;max-height:60vh;white-space:pre-wrap;overflow-wrap:anywhere}
.dlg-pre:focus-visible{outline:2px solid var(--focus)}

/* ---- recording mode: ?record=1. Anything meant only for a judge carries .judge-only and is hidden. */
.record .judge-only{display:none}
.record .bar{height:60px;gap:24px}
.record .word{font-size:26px}
.record .descriptor{font-size:17px;white-space:normal;line-height:1.25}
.record .tabs button{font-size:16px}
.record .findings h2,.record .tape h3{font-size:16px}
body.record{grid-template-rows:60px minmax(0,1fr) auto}

/* a short window (also a page zoomed to 160 percent): the loupe gets shorter so the sheet keeps room */
@media (min-width:900px) and (max-height:720px){
  .loupe{top:32px;height:150px}
  .ctx{top:12px}
  .controls{left:16px;right:16px;bottom:14px}
  .stage.partial .flatblock{top:calc(32px + 150px + 12px);bottom:70px}
}
@media (max-width:1100px){:root{--panel:360px}.main{grid-template-columns:minmax(0,1fr) var(--panel)}}
@media (max-width:899px){
  html,body{height:auto}
  body{display:block;min-height:100vh;overflow:auto;overflow-x:hidden;padding-bottom:calc(92px + env(safe-area-inset-bottom))}
  .bar{height:52px;gap:12px;padding:0 16px}.descriptor{display:none}
  .record .bar{height:60px}
  .brand{min-height:44px}
  .tabs{margin-left:auto}.tabs button{min-height:44px;padding:0 12px}
  .main{display:flex;flex-direction:column;padding:16px;gap:16px}
  body[data-state="first-run"] .main{display:block}
  .stage{height:clamp(264px,50vh,540px);flex:none}
  .stage::before{inset:6px}
  .loupe{top:32px;width:calc(100% - 24px);height:clamp(104px,18vh,150px)}
  .ctx{top:14px;left:20px;right:20px}
  .controls{left:12px;right:12px;bottom:8px;gap:0 8px}
  .controls button:not(.primary){min-height:44px;min-width:44px;padding:0 4px;font-size:14px}
  .pageno{font-size:13px;margin-left:auto}
  .dock{display:flex;flex-direction:column;align-items:stretch;gap:2px;position:fixed;z-index:30;left:0;right:0;bottom:0;padding:10px 16px calc(10px + env(safe-area-inset-bottom));background:var(--canvas);border-top:1px solid var(--line)}
  .dock .primary{min-height:48px;width:100%;order:0}
  .dock .hint{order:1;text-align:center}
  .panel{overflow:visible}
  .tape button.ln{min-height:44px;align-items:center}
  .list li{min-height:44px}
  .flist li.fnd{min-height:44px}
  .chip{min-height:44px;padding:0 14px}
  .btns button,.dlg-close{min-height:44px}
  .fails summary{min-height:44px;display:flex;align-items:center}
  .tape .pair .ln{font-size:13px}
